(24815,1,'2026-05-13 20:27:48','2026-05-13 18:27:48','<!-- wp:group {\"className\":\"iss-project-dossier\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-project-dossier\"><!-- wp:paragraph {\"className\":\"iss-project-dossier__lead\"} -->\n<p class=\"iss-project-dossier__lead\">Das Landmark der Elektropolis war ein zweiphasiger künstlerischer Wettbewerb für den Stadtplatz am Kaisersteg: eine weithin sichtbare Installation, die Schöneweides Industriegeschichte mit regenerativer Energie, Licht und Aufenthaltsqualität verbinden sollte.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:iss/dense-image-wall {\"items\":[{\"id\":1667,\"url\":\"/wp-content/uploads/2019/02/Entwurfsdarstellung_klein-1.jpg\",\"alt\":\"\",\"kicker\":\"\",\"title\":\"Entwurfsdarstellung_klein\",\"text\":\"\",\"caption\":\"\",\"captionHtml\":\"\",\"className\":\"\",\"captionClassName\":\"\",\"linkUrl\":\"\",\"colSpan\":2,\"rowSpan\":4},{\"id\":25267,\"url\":\"/wp-content/uploads/2026/05/Berlin_Kaisersteg_Oberschoeneweide_ZfB_1900-scaled.jpg\",\"alt\":\"\",\"kicker\":\"\",\"title\":\"Berlin_Kaisersteg_Oberschoeneweide_ZfB_1900\",\"text\":\"\",\"caption\":\"\",\"captionHtml\":\"\",\"className\":\"\",\"captionClassName\":\"\",\"linkUrl\":\"\",\"colSpan\":2,\"rowSpan\":4},{\"id\":6852,\"url\":\"/wp-content/uploads/2023/03/Blick-vom-Kaisersteg-1-jpg.webp\",\"alt\":\"\",\"kicker\":\"\",\"title\":\"Blick vom Kaisersteg\",\"text\":\"\",\"caption\":\"\",\"captionHtml\":\"\",\"className\":\"\",\"captionClassName\":\"\",\"linkUrl\":\"\",\"colSpan\":4,\"rowSpan\":4}]} -->\n<div class=\"wp-block-group iss-dense-image-wall\"><figure class=\"wp-block-image iss-dense-image-wall__cell iss-dense-image-wall__cell--wide iss-dense-image-wall__cell--tall iss-dense-image-wall__cell--captioned\" style=\"grid-column:span 2;grid-row:span 4\"><img src=\"/wp-content/uploads/2019/02/Entwurfsdarstellung_klein-1.jpg\" alt=\"\"/><figcaption class=\"iss-dense-image-wall__caption\"><p class=\"iss-dense-image-wall__title\">Entwurfsdarstellung_klein</p></figcaption></figure><figure class=\"wp-block-image iss-dense-image-wall__cell iss-dense-image-wall__cell--wide iss-dense-image-wall__cell--tall iss-dense-image-wall__cell--captioned\" style=\"grid-column:span 2;grid-row:span 4\"><img src=\"/wp-content/uploads/2026/05/Berlin_Kaisersteg_Oberschoeneweide_ZfB_1900-scaled.jpg\" alt=\"\"/><figcaption class=\"iss-dense-image-wall__caption\"><p class=\"iss-dense-image-wall__title\">Berlin_Kaisersteg_Oberschoeneweide_ZfB_1900</p></figcaption></figure><figure class=\"wp-block-image iss-dense-image-wall__cell iss-dense-image-wall__cell--wide iss-dense-image-wall__cell--tall iss-dense-image-wall__cell--captioned\" style=\"grid-column:span 4;grid-row:span 4\"><img src=\"/wp-content/uploads/2023/03/Blick-vom-Kaisersteg-1-jpg.webp\" alt=\"\"/><figcaption class=\"iss-dense-image-wall__caption\"><p class=\"iss-dense-image-wall__title\">Blick vom Kaisersteg</p></figcaption></figure></div>\n<!-- /wp:iss/dense-image-wall -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"iss-project-chapter\",\"layout\":{\"type\":\"default\"},\"anchor\":\"worum-es-geht\"} -->\n<section id=\"worum-es-geht\" class=\"wp-block-group iss-project-chapter\"><!-- wp:paragraph {\"className\":\"iss-project-chapter__kicker\"} -->\n<p class=\"iss-project-chapter__kicker\">Worum es geht</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Ein sichtbarer Energie-Ort für Schöneweide.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Auf dem zentralen Stadtplatz von Schöneweide sollte ein Landmark entstehen, das die frühere Elektropolis am Spreeufer charakterisiert. Der Anspruch war kein reines Denkzeichen, sondern eine künstlerische Installation mit Fernwirkung, Aufenthaltsqualität und eigener Energieproduktion.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Die Installation sollte Strom erzeugen, speichern und vor Ort nutzbar machen. Damit verbindet das Projekt historische Elektroindustrie, regenerative Energie und den öffentlichen Raum am Kaisersteg.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:columns {\"className\":\"iss-project-chapter__cards\"} -->\n<div class=\"wp-block-columns iss-project-chapter__cards\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"iss-context-panel\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-context-panel\"><!-- wp:paragraph {\"className\":\"iss-context-panel__label\"} -->\n<p class=\"iss-context-panel__label\">Ort</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Stadtplatz am Kaisersteg, zwischen Spree, Kranbahn und öffentlichem Uferraum.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"iss-context-panel\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-context-panel\"><!-- wp:paragraph {\"className\":\"iss-context-panel__label\"} -->\n<p class=\"iss-context-panel__label\">Energie</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Windrotoren, Speicherbatterie und Licht machen Energie als Funktion und Zeichen erfahrbar.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"iss-context-panel\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-context-panel\"><!-- wp:paragraph {\"className\":\"iss-context-panel__label\"} -->\n<p class=\"iss-context-panel__label\">Identität</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Das Landmark sollte als Hingucker, Identitätsanker und touristischer Einstieg in die Industriekultur wirken.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"iss-project-chapter\",\"layout\":{\"type\":\"default\"},\"anchor\":\"konzept\"} -->\n<section id=\"konzept\" class=\"wp-block-group iss-project-chapter\"><!-- wp:paragraph {\"className\":\"iss-project-chapter__kicker\"} -->\n<p class=\"iss-project-chapter__kicker\">Konzept</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Licht, Kupfer, Wind und öffentlicher Raum.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Der von der Jury empfohlene Entwurf <strong>Lichtgestalt Elektra</strong> von Peter Sandhaus interpretiert elektrische Energie abstrakt und konstruktiv. Er greift die Tradition der AEG, das Motiv der Elektra und die Materialgeschichte der Elektroindustrie auf, ohne ein historisches Zeichen direkt nachzubilden.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"className\":\"is-style-iss-list-rail\"} -->\n<ul class=\"wp-block-list is-style-iss-list-rail\"><!-- wp:list-item -->\n<li><strong>Drei Träger:</strong> Die Hauptstruktur verweist auf industrielle Kabel- und Kupferstränge und macht die Geschichte des Standorts vermittelbar.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>31 Meter Höhe:</strong> Die Lichtgestalt orientiert sich am Pylon des Kaiserstegs und soll über Platz und Spree hinweg sichtbar sein.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Wind und Speicher:</strong> Drei Windrotoren erzeugen Strom; eine Batterie unter der runden Bank speichert die Energie.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Licht und Nutzung:</strong> Die gespeicherte Energie speist die nächtliche Strahlkraft und sollte tagsüber auch mobile Geräte oder E-Bikes versorgen können.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Wirkung, die der Wettbewerb suchte.</h3>\n<!-- /wp:heading -->\n\n<!-- wp:list {\"className\":\"is-style-iss-list-facts\"} -->\n<ul class=\"wp-block-list is-style-iss-list-facts\"><!-- wp:list-item -->\n<li>Hingucker mit Fernwirkung am Schöneweider Spreeufer</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Identitätsanker für Bewohnerinnen und Bewohner</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>touristischer Anlaufpunkt für Industriekultur</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Aufwertung des Stadtplatzes und Verbesserung der Aufenthaltsqualität</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"iss-project-chapter\",\"layout\":{\"type\":\"default\"},\"anchor\":\"mitwirken\"} -->\n<section id=\"mitwirken\" class=\"wp-block-group iss-project-chapter\"><!-- wp:paragraph {\"className\":\"iss-project-chapter__kicker\"} -->\n<p class=\"iss-project-chapter__kicker\">Mitwirken</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Wettbewerb, Jury und Fachpartner.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Der Industriesalon Schöneweide lobte den Wettbewerb in den Jahren 2016 und 2017 aus. Die Realisierung des Wettbewerbs erfolgte in Kooperation mit dem Büro für Kunst im Öffentlichen Raum des Kulturwerks des bbk berlin; das Verfahren orientierte sich an den Richtlinien für Planungswettbewerbe RPW 2013.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"className\":\"is-style-iss-list-facts\"} -->\n<ul class=\"wp-block-list is-style-iss-list-facts\"><!-- wp:list-item -->\n<li><strong>Auslober:</strong> Industriesalon Schöneweide e.V.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Kooperation:</strong> Büro für Kunst im Öffentlichen Raum, Kulturwerk des bbk berlin GmbH.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Wettbewerb:</strong> zweiphasiges künstlerisches Verfahren mit insgesamt 31 Beiträgen.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Empfehlung:</strong> Eine siebenköpfige Jury empfahl am 19. Juni 2017 den Entwurf von Peter Sandhaus zur Realisierung.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Beteiligte Rollen im PDF-Dokument.</h3>\n<!-- /wp:heading -->\n\n<!-- wp:list {\"ordered\":true,\"className\":\"is-style-iss-list-steps\"} -->\n<ol class=\"wp-block-list is-style-iss-list-steps\"><!-- wp:list-item -->\n<li><strong>Fachpreisrichterinnen und Fachpreisrichter:</strong> Künstlerinnen, Künstler und Fachvertreterinnen aus Gestaltung und Kultur.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Sachpreisrichterinnen und Sachpreisrichter:</strong> Bezirk, Industriesalon und landschaftsplanerische Expertise.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Sachverständige:</strong> Verwaltung, Wirtschaftsförderung, Kunst im öffentlichen Raum, regenerative Energien und Senatsverwaltung.</li>\n<!-- /wp:list-item --></ol>\n<!-- /wp:list --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"iss-project-chapter iss-project-chapter\\u002d\\u002dwide\",\"layout\":{\"type\":\"default\"},\"anchor\":\"material\"} -->\n<section id=\"material\" class=\"wp-block-group iss-project-chapter iss-project-chapter--wide\"><!-- wp:paragraph {\"className\":\"iss-project-chapter__kicker\"} -->\n<p class=\"iss-project-chapter__kicker\">Material</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Entwurfsbild und Wettbewerbsdokumentation.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Die Materiallage ist klar begrenzt: ein direkt zugeordneter Entwurfsrender, eine vierseitige PDF-Dokumentation und Ortsfotos vom Kaisersteg. Allgemeine Elektropolis-Fotos aus der Mediathek bleiben Kontext und werden nicht als Wettbewerbsfotos ausgegeben.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:columns {\"verticalAlignment\":\"center\",\"className\":\"iss-project-chapter__cards\"} -->\n<div class=\"wp-block-columns are-vertically-aligned-center iss-project-chapter__cards\"><!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"40%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:40%\"><!-- wp:group {\"className\":\"iss-media-card iss-media-card\\u002d\\u002dcontain iss-media-card\\u002d\\u002dframed\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-media-card iss-media-card--contain iss-media-card--framed\"><!-- wp:image {\"id\":1014,\"sizeSlug\":\"large\",\"linkDestination\":\"custom\"} -->\n<figure class=\"wp-block-image size-large\"><a href=\"/wp-content/uploads/2019/10/Infos-zum-Landmark.pdf\"><img src=\"/wp-content/uploads/2019/10/Infos-zum-Landmark-pdf-725x1024.jpg\" alt=\"PDF-Vorschau Infos zum Landmark\" class=\"wp-image-1014\"/></a></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"60%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:60%\"><!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">PDF: Infos zum Landmark</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Die PDF enthält die Zusammenfassung des Wettbewerbs, die Anforderungen an das Landmark, die Juryempfehlung, das Konzept von Peter Sandhaus sowie die Zusammensetzung von Jury und Sachverständigen.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"className\":\"is-style-iss-list-facts\"} -->\n<ul class=\"wp-block-list is-style-iss-list-facts\"><!-- wp:list-item -->\n<li>vier Seiten, erstellt im Oktober 2018</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Auslobung und Wettbewerb 2016/2017</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Juryempfehlung vom 19. Juni 2017</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Konzepttext zu <strong>Lichtgestalt Elektra</strong></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"/wp-content/uploads/2019/10/Infos-zum-Landmark.pdf\">PDF öffnen</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"iss-project-chapter\",\"layout\":{\"type\":\"default\"},\"anchor\":\"rueckblick\"} -->\n<section id=\"rueckblick\" class=\"wp-block-group iss-project-chapter\"><!-- wp:paragraph {\"className\":\"iss-project-chapter__kicker\"} -->\n<p class=\"iss-project-chapter__kicker\">Rückblick</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Vom Wettbewerb zur dokumentierten Projektidee.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list {\"ordered\":true,\"className\":\"is-style-iss-list-steps\"} -->\n<ol class=\"wp-block-list is-style-iss-list-steps\"><!-- wp:list-item -->\n<li><strong>2016/2017:</strong> Der Industriesalon lobt einen zweiphasigen künstlerischen Wettbewerb für das Landmark aus.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>19. Juni 2017:</strong> Die Jury empfiehlt <strong>Lichtgestalt Elektra</strong> von Peter Sandhaus zur Realisierung.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Oktober 2018:</strong> Die PDF <strong>Infos zum Landmark</strong> fasst Wettbewerb, Juryempfehlung und Konzept zusammen.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>2019:</strong> Die Projektseite hält fest, dass der Industriesalon an einer belastbaren Kostenberechnung arbeitet.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Heute:</strong> Die Seite dient als Projektarchiv für Idee, Wettbewerb, Entwurf und Ortsbezug am Kaisersteg.</li>\n<!-- /wp:list-item --></ol>\n<!-- /wp:list --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"iss-project-chapter\",\"layout\":{\"type\":\"default\"},\"anchor\":\"kontakt\"} -->\n<section id=\"kontakt\" class=\"wp-block-group iss-project-chapter\"><!-- wp:paragraph {\"className\":\"iss-project-chapter__kicker\"} -->\n<p class=\"iss-project-chapter__kicker\">Kontakt</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Fragen zur Wettbewerbsdokumentation.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Für Rückfragen zur Dokumentation, zu historischen Projektständen oder zur Einordnung des Landmarks im Elektropolis-Kontext läuft der Einstieg über den allgemeinen </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:industriesalon/field {\"key\":\"contact.email\",\"tagName\":\"p\",\"linkMode\":\"email\",\"label\":\"E-Mail:\",\"hrefSuffix\":\"?subject=Landmark%20der%20Elektropolis\"} /--></section>\n<!-- /wp:group --></div>\n<!-- /wp:group -->','Das Landmark der Elektropolis','Das Landmark der Elektropolis war ein zweiphasiger künstlerischer Wettbewerb für den Stadtplatz am Kaisersteg: eine weithin sichtbare Installation, die Schöneweides Industriegeschichte mit regenerativer Energie, Licht und Aufenthaltsqualität verbinden sollte.','publish','closed','closed','','das-landmark-der-elektropolis','','','2026-06-14 21:20:06','2026-06-14 19:20:06','',0,'/projekte/das-landmark-der-elektropolis/',60,'projekt','',0),
(24816,1,'2026-05-13 20:27:48','2026-05-13 18:27:48','<!-- wp:group {\"className\":\"iss-project-dossier\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-project-dossier\"><!-- wp:paragraph {\"className\":\"iss-project-dossier__lead\"} -->\n<p class=\"iss-project-dossier__lead\">Connected by Lights denkt die Spree als verbindende Bühne: ein künstlerisches Lichtfestival zwischen Berliner Mitte und Altstadt Köpenick, bei dem Ufer, Brücken, Gebäude und Schiffe zu einem gemeinsamen Lichtparcours werden.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"className\":\"iss-dense-image-wall\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-dense-image-wall\"><!-- wp:group {\"className\":\"iss-dense-image-wall__cell iss-dense-image-wall__cell\\u002d\\u002dwide iss-dense-image-wall__cell\\u002d\\u002dcaptioned\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-dense-image-wall__cell iss-dense-image-wall__cell--wide iss-dense-image-wall__cell--captioned\"><!-- wp:image {\"id\":2459,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"/wp-content/uploads/2021/04/connecting_lights-1024x723.jpg\" alt=\"Lichtstimmung an der Spree als Projektmotiv für Connected by Lights\" class=\"wp-image-2459\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:group {\"className\":\"iss-dense-image-wall__caption\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-dense-image-wall__caption\"><!-- wp:paragraph -->\n<p><strong>Spree als Bühne</strong><span>Die Route wird vom Wasser aus gelesen.</span></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"iss-project-chapter\",\"layout\":{\"type\":\"default\"},\"anchor\":\"worum-es-geht\"} -->\n<section id=\"worum-es-geht\" class=\"wp-block-group iss-project-chapter\"><!-- wp:paragraph {\"className\":\"iss-project-chapter__kicker\"} -->\n<p class=\"iss-project-chapter__kicker\">Worum es geht</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Eine leuchtende Verbindung auf der Spree.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Der Industriesalon engagiert sich für ein künstlerisches Lichtfestival, das Berlinerinnen, Berliner und Gäste einlädt, Treptow-Köpenick vom Wasser aus zu entdecken. Die Ufer der Spree werden nicht als Rand, sondern als Bühne verstanden: Fassaden, Brücken, Hafenkanten, Industriebauten und Schiffe bilden zusammen eine temporäre Galerie.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Im Mittelpunkt stehen vierzehn ausgewählte Wettbewerbsentwürfe. Sie reichen von Projektionen und interaktiven Schattenbildern über leuchtende Textzeichen, Brückeninszenierungen und wiederkehrende Leuchtelemente bis zu Arbeiten, die konkrete Orte der Industriegeschichte aufnehmen.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:columns {\"className\":\"iss-project-chapter__cards\"} -->\n<div class=\"wp-block-columns iss-project-chapter__cards\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"iss-context-panel\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-context-panel\"><!-- wp:paragraph {\"className\":\"iss-context-panel__label\"} -->\n<p class=\"iss-context-panel__label\">14 Entwürfe</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Lichtkunst, Brückenlicht und ein verbindendes Leuchtelement aus dem Wettbewerb.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"iss-context-panel\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-context-panel\"><!-- wp:paragraph {\"className\":\"iss-context-panel__label\"} -->\n<p class=\"iss-context-panel__label\">Spree-Route</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Vom Zentrum Berlins über Treptow und Schöneweide bis in Richtung Altstadt Köpenick.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"iss-context-panel\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-context-panel\"><!-- wp:paragraph {\"className\":\"iss-context-panel__label\"} -->\n<p class=\"iss-context-panel__label\">Vom Schiff lesbar</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Der Parcours ist für Passagiere gedacht, bleibt aber auch am Ufer sichtbar.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"iss-project-chapter\",\"layout\":{\"type\":\"default\"},\"anchor\":\"konzept\"} -->\n<section id=\"konzept\" class=\"wp-block-group iss-project-chapter\"><!-- wp:paragraph {\"className\":\"iss-project-chapter__kicker\"} -->\n<p class=\"iss-project-chapter__kicker\">Konzept</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Route, Wettbewerb, Anrainer.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Connected by Lights verbindet drei Ebenen: eine kuratierte Route auf der Spree, einen offenen Wettbewerb für künstlerische Arbeiten und die Einladung an Anrainer, ihre Gebäude und Ufer gemeinsam mit Künstlerinnen und Künstlern zu inszenieren. So entsteht kein einzelnes Objekt, sondern ein zusammenhängender Lichtzusammenhang entlang des Wassers.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"ordered\":true,\"className\":\"is-style-iss-list-steps\"} -->\n<ol class=\"wp-block-list is-style-iss-list-steps\"><!-- wp:list-item -->\n<li><strong>Einzelne Lichtkunstwerke:</strong> temporäre Arbeiten an Fassaden, Industriebauten, Uferzonen, Häfen und markanten Orten entlang der Spree.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Brücken:</strong> eine eigene Brückenidee, die die Durchfahrt des Schiffes als Bewegung durch Lichtbögen inszeniert.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Leuchtelement:</strong> ein wiederkehrendes Zeichen, das an Anlegestellen und Stationen die Route zusammenhält.</li>\n<!-- /wp:list-item --></ol>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Was die Route leisten soll.</h3>\n<!-- /wp:heading -->\n\n<!-- wp:list {\"className\":\"is-style-iss-list-rail\"} -->\n<ul class=\"wp-block-list is-style-iss-list-rail\"><!-- wp:list-item -->\n<li><strong>Verbindung statt Kulisse:</strong> Die Spree wird als gemeinsamer Raum gelesen, nicht nur als schöne Strecke zwischen einzelnen Sehenswürdigkeiten.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Industriegeschichte sichtbar machen:</strong> Schöneweider Orte wie ehemalige Fabriken, Brauereien, Uferanlagen und technische Bauwerke werden Teil der künstlerischen Erzählung.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Publikum aktivieren:</strong> Einige Beiträge denken Passagiere, Schatten, Bewegung, Projektion oder Wind als Bestandteil der Arbeit mit.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Anrainer einbinden:</strong> Eigentümer, Betreiber und Nachbarschaft sollen nicht nur Gastgeber sein, sondern die Wirkung ihrer Orte mitgestalten.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"iss-project-chapter\",\"layout\":{\"type\":\"default\"},\"anchor\":\"mitwirken\"} -->\n<section id=\"mitwirken\" class=\"wp-block-group iss-project-chapter\"><!-- wp:paragraph {\"className\":\"iss-project-chapter__kicker\"} -->\n<p class=\"iss-project-chapter__kicker\">Mitwirken</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Kunst, Ufer, Schiff und Nachbarschaft.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Das Projekt ist nur als Verbund denkbar. Es braucht künstlerische Entwürfe, geeignete Orte, technische Abstimmung, Eigentümer, Genehmigungen, Schiffsbetrieb und ein Publikum, das die Route als gemeinsames Erlebnis wahrnimmt.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"className\":\"is-style-iss-list-rail\"} -->\n<ul class=\"wp-block-list is-style-iss-list-rail\"><!-- wp:list-item -->\n<li><strong>Künstlerinnen und Künstler:</strong> entwickeln Arbeiten, die aus Entfernung, in Bewegung und bei Nacht funktionieren.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Anrainer und Eigentümer:</strong> öffnen Fassaden, Ufer, Dächer, Fenster oder Freiflächen als Träger der Lichtarbeiten.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Schiffsbetrieb und Publikum:</strong> machen die Route zeitlich erfahrbar; manche Entwürfe reagieren direkt auf Passagiere oder vorbeifahrende Schiffe.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Partner aus Kultur und Verwaltung:</strong> sichern Auswahl, Genehmigung, Vermittlung und öffentliche Sichtbarkeit.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Offene Arbeitsfragen.</h3>\n<!-- /wp:heading -->\n\n<!-- wp:list {\"className\":\"is-style-iss-list-facts\"} -->\n<ul class=\"wp-block-list is-style-iss-list-facts\"><!-- wp:list-item -->\n<li>Welche Orte können technisch, rechtlich und organisatorisch tatsächlich bespielt werden?</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Welche Beiträge funktionieren temporär, ohne die Orte baulich zu überformen?</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Welche Stationen sind vom Schiff, vom Ufer und aus der Nachbarschaft gleichermaßen lesbar?</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Welche Partner tragen Strom, Sicherheit, Vermittlung, Schiffsbetrieb und Kommunikation?</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"iss-project-chapter iss-project-chapter\\u002d\\u002dwide\",\"layout\":{\"type\":\"default\"},\"anchor\":\"material\"} -->\n<section id=\"material\" class=\"wp-block-group iss-project-chapter iss-project-chapter--wide\"><!-- wp:paragraph {\"className\":\"iss-project-chapter__kicker\"} -->\n<p class=\"iss-project-chapter__kicker\">Material</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Vierzehn Wettbewerbsbeiträge als offenes Material.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Die PDF-Anlage dokumentiert die ausgewählten Wettbewerbsbeiträge in drei Teilen. Für die Projektseite werden sie nicht als lose Datei versteckt, sondern als Arbeitsmaterial sichtbar gemacht: Titel, Autorinnen und Autoren, Ortshinweise und Grundidee bleiben auffindbar.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Wettbewerbsteil I: einzelne Lichtkunstwerke.</h3>\n<!-- /wp:heading -->\n\n<!-- wp:list {\"ordered\":true,\"className\":\"is-style-iss-list-steps\"} -->\n<ol class=\"wp-block-list is-style-iss-list-steps\"><!-- wp:list-item -->\n<li><strong>Do it yourself, Anastasia Mikhaylova:</strong> mobile Diaprojektoren für Bootspassagiere; Besucherinnen und Besucher werfen eigene Lichtbotschaften in die Umgebung.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>play of light and shadow, Charlotte Bach:</strong> eine interaktive Fassadenprojektion, in der Bewegungen des Publikums zu farbigen Schattenbildern werden.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Aber vielleicht woanders, Holger Beisitzer:</strong> ein roter Leuchtschriftzug, der wie ein Werbeversprechen wirkt und zugleich offen lässt, wohin das Versprechen zeigt.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Verbindungslinien, Antje Blumenstein:</strong> Linien und Dreiecke markieren räumliche, historische und wasserbauliche Verbindungen am Britzer Verbindungskanal.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Lichtintervention, Eberhard Bosslet:</strong> Stroboskopblitze verändern die nächtliche Wirkung des historischen Kranhauses in Schöneweide.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Nachleuchten, Michael Bühler:</strong> nachleuchtende Farbmuster am Treptower Hafen verweisen auf das langsame Zusammenwachsen von Stadträumen.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Lichtkunstwerk, Knut Eckstein:</strong> ein temporäres Objekt aus Lichtschläuchen, das Zeichen aus Werbung, Logo und Graffiti in ein Flussufer-Objekt übersetzt.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Reflective Flag, Markus Hoffmann und Elias Keimer:</strong> eine große reflektierende Fahne, deren Erscheinung sich mit Licht, Wind und Wetter verändert.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>auSmACHEN (Matter/Matters), Stephanie Imbeau:</strong> verbundene Schirmgruppen bilden leuchtende Gemeinschaftsstrukturen an oder nahe der Spree.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Spreewürfel, Annelen Käferstein:</strong> ein warm leuchtender grüner Glaswürfel verdichtet Fluss, Urstromtal, Stadtursprung und Transformation zu einem Objekt.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>...still loading, Antje Osterburg / bo_(backoffice) Berlin:</strong> Fenster der Pertrix-Batteriefabrik werden zu einer Lichtanzeige, die durch vorbeifahrende Schiffe aktiviert wird.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Schöneweidebär, Natalia Irina Roman:</strong> eine animierte Lichtfigur greift den Bären der Bärenquell- beziehungsweise Borussia-Brauerei auf und macht Wartestand und Erinnerung sichtbar.</li>\n<!-- /wp:list-item --></ol>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Wettbewerbsteil II und III: Brücken und Leuchtelement.</h3>\n<!-- /wp:heading -->\n\n<!-- wp:list {\"className\":\"is-style-iss-list-facts\"} -->\n<ul class=\"wp-block-list is-style-iss-list-facts\"><!-- wp:list-item -->\n<li><strong>Lichtbögen, Günter Ries:</strong> die Unterseiten von zehn Brücken werden so beleuchtet, dass das Schiff in einen Lichtbogen hineinfährt.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>H2O-Molekül, Tina Zimmermann und Constantin Rainer:</strong> ein wiederkehrendes Wassermolekül dient als identitätsstiftendes Lichtzeichen an Stationen und Anlegestellen.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:columns {\"verticalAlignment\":\"center\",\"className\":\"iss-project-chapter__cards\"} -->\n<div class=\"wp-block-columns are-vertically-aligned-center iss-project-chapter__cards\"><!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"34%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:34%\"><!-- wp:group {\"className\":\"iss-media-card iss-media-card\\u002d\\u002dcontain iss-media-card\\u002d\\u002dframed\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-media-card iss-media-card--contain iss-media-card--framed\"><!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"custom\"} -->\n<figure class=\"wp-block-image size-large\"><a href=\"/wp-content/uploads/2020/11/Anlage_Lichtkunstwerke.pdf\"><img src=\"/wp-content/uploads/2020/11/Anlage_Lichtkunstwerke-pdf-724x1024.jpg\" alt=\"Vorschau der PDF-Anlage mit ausgewählten Lichtkunstwerken\"/></a></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"66%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:66%\"><!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">PDF-Anlage: Wettbewerbsdokumentation</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Die Anlage bleibt das vollständige Arbeitsdokument des Wettbewerbs. Die Projektseite zeigt die Beiträge im Überblick; die PDF bewahrt Entwurfsblätter, Reihenfolge und Originalkontext.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"/wp-content/uploads/2020/11/Anlage_Lichtkunstwerke.pdf\">PDF öffnen</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"iss-project-chapter\",\"layout\":{\"type\":\"default\"},\"anchor\":\"rueckblick\"} -->\n<section id=\"rueckblick\" class=\"wp-block-group iss-project-chapter\"><!-- wp:paragraph {\"className\":\"iss-project-chapter__kicker\"} -->\n<p class=\"iss-project-chapter__kicker\">Rückblick</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Ein Wettbewerb, der das Projekt greifbar gemacht hat.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Connected by Lights ist als Vorbereitungsidee und Wettbewerbsstand überliefert. Die Seite hält diesen Stand bewusst fest: nicht als fertiges Festivalprogramm, sondern als ausformuliertes Projektmaterial, das zeigt, welche künstlerische und räumliche Qualität die Route haben könnte.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"ordered\":true,\"className\":\"is-style-iss-list-steps\"} -->\n<ol class=\"wp-block-list is-style-iss-list-steps\"><!-- wp:list-item -->\n<li><strong>Festivalidee:</strong> Der Industriesalon formuliert eine Lichtfestival-Route, die Berliner Mitte, Treptow, Schöneweide und Köpenick über die Spree verbindet.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Wettbewerb:</strong> In Kooperation mit dem Büro für Kunst im öffentlichen Raum des bbk wird ein Kunstwettbewerb vorbereitet und durchgeführt.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Jury-Auswahl:</strong> Eine Fachjury wählt Entwürfe für einzelne Lichtkunstwerke, Brücken und ein verbindendes Leuchtelement aus.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Dokumentation:</strong> Die ausgewählten Arbeiten werden in der PDF-Anlage festgehalten und bleiben als Projektarchiv verfügbar.</li>\n<!-- /wp:list-item --></ol>\n<!-- /wp:list --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"iss-project-chapter\",\"layout\":{\"type\":\"default\"},\"anchor\":\"kontakt\"} -->\n<section id=\"kontakt\" class=\"wp-block-group iss-project-chapter\"><!-- wp:paragraph {\"className\":\"iss-project-chapter__kicker\"} -->\n<p class=\"iss-project-chapter__kicker\">Kontakt</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Projektfragen und Anschluss.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Für Nachfragen zur Wettbewerbsdokumentation, zu möglichen Anschlussformaten oder zu Orten entlang der Route ist der allgemeine Kontakt des Industriesalon der richtige Einstieg. </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:industriesalon/field {\"key\":\"contact.email\",\"tagName\":\"p\",\"linkMode\":\"email\",\"label\":\"E-Mail:\",\"hrefSuffix\":\"?subject=Connected%20by%20Lights\"} /--></section>\n<!-- /wp:group --></div>\n<!-- /wp:group -->','Connected by Lights','Das künstlerische Lichtfestival auf der Spree zwischen Berliner Mitte und Altstadt Köpenick: 14 Wettbewerbsentwürfe verbinden Ufer, Brücken, Gebäude und Publikum zu einem leuchtenden Parcours.','publish','closed','closed','','connected-by-lights','','','2026-06-14 21:24:33','2026-06-14 19:24:33','',0,'/projekte/connected-by-lights/',50,'projekt','',0),
(24817,1,'2026-05-13 20:27:48','2026-05-13 18:27:48','<!-- wp:group {\"className\":\"iss-project-dossier\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-project-dossier\"><!-- wp:paragraph {\"className\":\"iss-project-dossier__lead\"} -->\n<p class=\"iss-project-dossier__lead\">Der Boulevard der Industriekultur ist eine Projektidee für die Wilhelminenhofstraße: Industriegeschichte, öffentliche Orte und aktuelle Transformation sollen zu einer lesbaren Route durch Schöneweide verbunden werden.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:iss/dense-image-wall {\"editMode\":\"annotate\",\"items\":[{\"id\":5443,\"url\":\"/wp-content/uploads/2022/06/Boulevard-Foto1.jpg\",\"alt\":\"\",\"kicker\":\"\",\"title\":\"\",\"text\":\"\",\"caption\":\"\",\"captionHtml\":\"\",\"className\":\"\",\"captionClassName\":\"\",\"linkUrl\":\"\",\"colSpan\":2,\"rowSpan\":3},{\"id\":10751,\"url\":\"/wp-content/uploads/2025/07/klingender_boulevard_website.png\",\"alt\":\"\",\"kicker\":\"\",\"title\":\"\",\"text\":\"\",\"caption\":\"\",\"captionHtml\":\"\",\"className\":\"\",\"captionClassName\":\"\",\"linkUrl\":\"\",\"colSpan\":2,\"rowSpan\":5},{\"id\":7485,\"url\":\"/wp-content/uploads/2023/05/Peter-Behrens-Bau-FH-1-jpg.webp\",\"alt\":\"\",\"kicker\":\"\",\"title\":\"\",\"text\":\"\",\"caption\":\"\",\"captionHtml\":\"\",\"className\":\"\",\"captionClassName\":\"\",\"linkUrl\":\"\",\"colSpan\":1,\"rowSpan\":2},{\"id\":2086,\"url\":\"/wp-content/uploads/2021/01/bulle_1.jpg\",\"alt\":\"\",\"kicker\":\"\",\"title\":\"\",\"text\":\"\",\"caption\":\"\",\"captionHtml\":\"\",\"className\":\"\",\"captionClassName\":\"\",\"linkUrl\":\"\",\"colSpan\":1,\"rowSpan\":2},{\"id\":7509,\"url\":\"/wp-content/uploads/2023/05/2013-01-26_13-01-25-Kaiserstieg-Panorama-02_20x30x300dpi_80-1-scaled-1.webp\",\"alt\":\"\",\"kicker\":\"\",\"title\":\"\",\"text\":\"\",\"caption\":\"\",\"captionHtml\":\"\",\"className\":\"\",\"captionClassName\":\"\",\"linkUrl\":\"\",\"colSpan\":4,\"rowSpan\":2}]} -->\n<div class=\"wp-block-group iss-dense-image-wall\"><figure class=\"wp-block-image iss-dense-image-wall__cell iss-dense-image-wall__cell--wide iss-dense-image-wall__cell--tall\" style=\"grid-column:span 2;grid-row:span 3\"><img src=\"/wp-content/uploads/2022/06/Boulevard-Foto1.jpg\" alt=\"\"/></figure><figure class=\"wp-block-image iss-dense-image-wall__cell iss-dense-image-wall__cell--wide iss-dense-image-wall__cell--tall\" style=\"grid-column:span 2;grid-row:span 5\"><img src=\"/wp-content/uploads/2025/07/klingender_boulevard_website.png\" alt=\"\"/></figure><figure class=\"wp-block-image iss-dense-image-wall__cell iss-dense-image-wall__cell--tall\" style=\"grid-row:span 2\"><img src=\"/wp-content/uploads/2023/05/Peter-Behrens-Bau-FH-1-jpg.webp\" alt=\"\"/></figure><figure class=\"wp-block-image iss-dense-image-wall__cell iss-dense-image-wall__cell--tall\" style=\"grid-row:span 2\"><img src=\"/wp-content/uploads/2021/01/bulle_1.jpg\" alt=\"\"/></figure><figure class=\"wp-block-image iss-dense-image-wall__cell iss-dense-image-wall__cell--wide iss-dense-image-wall__cell--tall\" style=\"grid-column:span 4;grid-row:span 2\"><img src=\"/wp-content/uploads/2023/05/2013-01-26_13-01-25-Kaiserstieg-Panorama-02_20x30x300dpi_80-1-scaled-1.webp\" alt=\"\"/></figure></div>\n<!-- /wp:iss/dense-image-wall -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"iss-project-chapter\",\"layout\":{\"type\":\"default\"},\"anchor\":\"worum-es-geht\"} -->\n<section id=\"worum-es-geht\" class=\"wp-block-group iss-project-chapter\"><!-- wp:paragraph {\"className\":\"iss-project-chapter__kicker\"} -->\n<p class=\"iss-project-chapter__kicker\">Worum es geht</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Eine Straße wird als Route lesbar.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Die Wilhelminenhofstraße erinnert auf den ersten Blick wenig an einen klassischen Boulevard. Gerade darin liegt der Ansatz der Projektidee: historische Produktionsbauten, Läden, Wohnhäuser, Transformationsflächen und Spreeufer sollen nicht als Einzelstücke stehen bleiben, sondern als zusammenhängender Stadtraum erfahrbar werden.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Schöneweide ist ein Schlüsselort der Berliner Elektropolis. Der Boulevard der Industriekultur will diese Geschichte öffnen, in den Alltag holen und mit der laufenden Entwicklung des Quartiers verbinden.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:columns {\"className\":\"iss-project-chapter__cards\"} -->\n<div class=\"wp-block-columns iss-project-chapter__cards\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"iss-context-panel\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-context-panel\"><!-- wp:paragraph {\"className\":\"iss-context-panel__label\"} -->\n<p class=\"iss-context-panel__label\">Straße</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Die Wilhelminenhofstraße bildet die Achse zwischen Produktionsgeschichte, Nachbarschaft und neuen Nutzungen.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"iss-context-panel\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-context-panel\"><!-- wp:paragraph {\"className\":\"iss-context-panel__label\"} -->\n<p class=\"iss-context-panel__label\">Geschichte</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Elektroindustrie, Transformatoren, Röhren, Kabel und Industriebahn werden als Orte im Stadtraum sichtbar.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"iss-context-panel\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-context-panel\"><!-- wp:paragraph {\"className\":\"iss-context-panel__label\"} -->\n<p class=\"iss-context-panel__label\">Gegenwart</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Start-ups, Wissenschaft, Forschung, Kunst und neue Produktion verändern die früheren Industrieareale.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"iss-project-chapter\",\"layout\":{\"type\":\"default\"},\"anchor\":\"konzept\"} -->\n<section id=\"konzept\" class=\"wp-block-group iss-project-chapter\"><!-- wp:paragraph {\"className\":\"iss-project-chapter__kicker\"} -->\n<p class=\"iss-project-chapter__kicker\">Konzept</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Erlebnisorte statt Schautafeln allein.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Der Boulevard soll industrielle Vergangenheit nicht nur erklären, sondern im öffentlichen Raum erlebbar machen. Die Quelltexte sprechen von Erlebnisorten entlang der Wilhelminenhofstraße bis zur Spree: kleine Interventionen, experimentelle Stationen, Ausstellungen, Gastronomie und Museumsorte können zusammen eine offene Route bilden.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"className\":\"is-style-iss-list-rail\"} -->\n<ul class=\"wp-block-list is-style-iss-list-rail\"><!-- wp:list-item -->\n<li><strong>Objekte im Außenraum:</strong> Technik, Spuren und historische Geräte können als sichtbare Marker im Stadtraum stehen.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Interaktive Installationen:</strong> Besucherinnen und Besucher sollen hören, ausprobieren, sehen und sich bewegen können.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Experimentierstationen:</strong> Elektrotechnik und Industriekultur werden über einfache, erfahrbare Versuchsanordnungen vermittelt.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Ausstellungen und Gastronomie:</strong> Bestehende oder neue Orte können Vermittlung, Aufenthalt und Alltag verbinden.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Die Leitfrage.</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Wie kann sich die Elektropolis als attraktiver Berliner Zukunftsort präsentieren, ohne ihre Industriegeschichte zu glätten? Die Idee ist keine abgeschlossene Bauplanung, sondern ein Rahmen, in dem Eigentümer, Projektentwickler, Anwohnerinnen und lokale Akteure sichtbare Beiträge leisten können.</p>\n<!-- /wp:paragraph --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"iss-project-chapter\",\"layout\":{\"type\":\"default\"},\"anchor\":\"mitwirken\"} -->\n<section id=\"mitwirken\" class=\"wp-block-group iss-project-chapter\"><!-- wp:paragraph {\"className\":\"iss-project-chapter__kicker\"} -->\n<p class=\"iss-project-chapter__kicker\">Mitwirken</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Ein offenes Konzept braucht lokale Partner.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Die alten Projekttexte stellen die Boulevard-Idee ausdrücklich als Einladung vor. Der Industriesalon suchte Ideen, starke Partner und Abstimmung mit Menschen, die vor Ort entwickeln, besitzen, arbeiten oder wohnen.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"className\":\"is-style-iss-list-facts\"} -->\n<ul class=\"wp-block-list is-style-iss-list-facts\"><!-- wp:list-item -->\n<li><strong>Eigentümer und Projektentwickler:</strong> Sie entscheiden über Zugänge, Nutzungen und Investitionen auf den Industriearealen.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Unternehmen und Initiativen:</strong> Sie können Orte öffnen, Geschichten beisteuern und neue Formate tragen.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Anwohnerinnen und Anwohner:</strong> Der Boulevard soll nicht nur touristisch wirken, sondern den Alltag im Quartier verbessern.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Projektgruppe:</strong> Genannt werden Kompetenzen aus Stadtplanung, Architektur, Zukunftsforschung, Tourismus und digitaler Umsetzung.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>Im Hintergrund steht ein pragmatischer Gedanke: Wenn neue Erlebnisorte die Identität und Attraktivität der Standorte stärken, profitieren auch Eigentümer, Unternehmen und Nachbarschaft.</p>\n<!-- /wp:paragraph --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"iss-project-chapter iss-project-chapter\\u002d\\u002dwide\",\"layout\":{\"type\":\"default\"},\"anchor\":\"material\"} -->\n<section id=\"material\" class=\"wp-block-group iss-project-chapter iss-project-chapter--wide\"><!-- wp:paragraph {\"className\":\"iss-project-chapter__kicker\"} -->\n<p class=\"iss-project-chapter__kicker\">Material</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Motive, Beispiele und vorhandene Quellen.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Die direkte Materiallage besteht aus den zwei Quellbeiträgen von 2022, dem Boulevard-Projektbild und ergänzenden Medien im Bestand des Industriesalon. Kontextmaterial wird als Kontext eingeordnet, nicht als abgeschlossene Projektdokumentation.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:columns {\"verticalAlignment\":\"center\",\"className\":\"iss-project-chapter__cards\"} -->\n<div class=\"wp-block-columns are-vertically-aligned-center iss-project-chapter__cards\"><!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"40%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:40%\"><!-- wp:group {\"className\":\"iss-media-card iss-media-card\\u002d\\u002dcover iss-media-card\\u002d\\u002dframed\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-media-card iss-media-card--cover iss-media-card--framed\"><!-- wp:image {\"id\":5443,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"/wp-content/uploads/2022/06/Boulevard-Foto1.jpg\" alt=\"Boulevard der Industriekultur, Projektbild zur Wilhelminenhofstraße\" class=\"wp-image-5443\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"60%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:60%\"><!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Drei Beispielideen aus den Quelltexten.</h3>\n<!-- /wp:heading -->\n\n<!-- wp:list {\"className\":\"is-style-iss-list-rail\"} -->\n<ul class=\"wp-block-list is-style-iss-list-rail\"><!-- wp:list-item -->\n<li><strong>Singende Trafos:</strong> Historische Transformatoren im ehemaligen TRO könnten als Klang- und Kunstobjekte Stimmen der Fabrikgeschichte hörbar machen.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Der Bulle:</strong> Eine virtuelle Führerstandsmitfahrt durch die früheren Werksanschlüsse kann die Industriebahn als Bewegung durch das Quartier zeigen.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Elektronenröhren-Show:</strong> Die frühere Vorführung aus dem WF-Kontext wird als mögliche neue Form an einem authentischen Ort genannt.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"/video/der-bulle-fahrt-im-fuhrerstand-der-industriebahn-durch-oberschoneweide/\">Video „Der Bulle“ öffnen</a></div>\n<!-- /wp:button -->\n\n<!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"/video/das-farbbildrohrenwerk-der-ddr-teil-vom-werk-fur-fernsehelektronik-wf/\">Video Farbbildröhrenwerk</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"iss-project-chapter\",\"layout\":{\"type\":\"default\"},\"anchor\":\"rueckblick\"} -->\n<section id=\"rueckblick\" class=\"wp-block-group iss-project-chapter\"><!-- wp:paragraph {\"className\":\"iss-project-chapter__kicker\"} -->\n<p class=\"iss-project-chapter__kicker\">Rückblick</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Konzeptstand aus der Transformationsphase.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Die beiden Quellbeiträge wurden am 20. Juni 2022 angelegt. Sie beschreiben eine vorbereitende Projektidee in einer Phase, in der sich Schöneweide sichtbar veränderte und mehrere Industrieareale neu entwickelt wurden.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"ordered\":true,\"className\":\"is-style-iss-list-steps\"} -->\n<ol class=\"wp-block-list is-style-iss-list-steps\"><!-- wp:list-item -->\n<li><strong>2022:</strong> Der Industriesalon formuliert den Boulevard der Industriekultur als Projektidee in Vorbereitung.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Ausgangspunkt:</strong> Die Wilhelminenhofstraße soll nicht als Prachtstraße behauptet, sondern aus ihren vorhandenen Qualitäten entwickelt werden.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Arbeitsrichtung:</strong> Erlebnisorte, Kooperationen und beispielhafte Interventionen sollen die Elektropolis im Stadtraum vermitteln.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Heute:</strong> Die Projektseite bewahrt den Konzeptstand und bindet ihn an Orte, Medien und zentrale Kontaktdaten an.</li>\n<!-- /wp:list-item --></ol>\n<!-- /wp:list --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"iss-project-chapter\",\"layout\":{\"type\":\"default\"},\"anchor\":\"kontakt\"} -->\n<section id=\"kontakt\" class=\"wp-block-group iss-project-chapter\"><!-- wp:paragraph {\"className\":\"iss-project-chapter__kicker\"} -->\n<p class=\"iss-project-chapter__kicker\">Kontakt</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Ideen und Rückfragen zum Boulevard.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Für Hinweise, Materialien, Projektideen oder Rückfragen zum Boulevard der Industriekultur läuft der Einstieg über den allgemeinen Kontakt des Industriesalon. </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:industriesalon/field {\"key\":\"contact.email\",\"tagName\":\"p\",\"linkMode\":\"email\",\"label\":\"E-Mail:\",\"hrefSuffix\":\"?subject=Boulevard%20der%20Industriekultur\"} /--></section>\n<!-- /wp:group --></div>\n<!-- /wp:group -->','Boulevard der Industriekultur','Der Boulevard der Industriekultur ist eine Projektidee für die Wilhelminenhofstraße: Industriegeschichte, öffentliche Orte und aktuelle Transformation sollen zu einer lesbaren Route durch Schöneweide verbunden werden.','publish','closed','closed','','boulevard-der-industriekultur','','','2026-06-14 21:22:13','2026-06-14 19:22:13','',0,'/projekte/boulevard-der-industriekultur/',20,'projekt','',0),
(24818,1,'2026-05-13 20:27:48','2026-05-13 18:27:48','<!-- wp:group {\"className\":\"iss-project-dossier\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-project-dossier\"><!-- wp:paragraph {\"className\":\"iss-project-dossier__lead\"} -->\n<p class=\"iss-project-dossier__lead\">Stadtlabor Wilhelminenhofstraße war eine wachsende Ausstellung und ein Nachbarschaftsexperiment zur wichtigsten Straße Oberschöneweides: Erinnerungen, Bilder, Archivmaterial und Wünsche wurden vor Ort gesammelt und als Ausstellung im Prozess sichtbar gemacht.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:iss/dense-image-wall {\"editMode\":\"annotate\",\"items\":[{\"id\":5782,\"url\":\"/wp-content/uploads/2022/09/SUE_Logo_Stadtlabor_Wortmarke_Rot-scaled.png\",\"alt\":\"\",\"kicker\":\"\",\"title\":\"\",\"text\":\"\",\"caption\":\"\",\"captionHtml\":\"\",\"className\":\"\",\"captionClassName\":\"\",\"linkUrl\":\"\",\"colSpan\":2,\"rowSpan\":4},{\"id\":5783,\"url\":\"/wp-content/uploads/2022/09/Stadtlabor_2.jpg\",\"alt\":\"\",\"kicker\":\"\",\"title\":\"\",\"text\":\"\",\"caption\":\"\",\"captionHtml\":\"\",\"className\":\"\",\"captionClassName\":\"\",\"linkUrl\":\"\",\"colSpan\":2,\"rowSpan\":4}]} -->\n<div class=\"wp-block-group iss-dense-image-wall\"><figure class=\"wp-block-image iss-dense-image-wall__cell iss-dense-image-wall__cell--wide iss-dense-image-wall__cell--tall\" style=\"grid-column:span 2;grid-row:span 4\"><img src=\"/wp-content/uploads/2022/09/SUE_Logo_Stadtlabor_Wortmarke_Rot-scaled.png\" alt=\"\"/></figure><figure class=\"wp-block-image iss-dense-image-wall__cell iss-dense-image-wall__cell--wide iss-dense-image-wall__cell--tall\" style=\"grid-column:span 2;grid-row:span 4\"><img src=\"/wp-content/uploads/2022/09/Stadtlabor_2.jpg\" alt=\"\"/></figure></div>\n<!-- /wp:iss/dense-image-wall -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"iss-project-chapter\",\"layout\":{\"type\":\"default\"},\"anchor\":\"worum-es-geht\"} -->\n<section id=\"worum-es-geht\" class=\"wp-block-group iss-project-chapter\"><!-- wp:paragraph {\"className\":\"iss-project-chapter__kicker\"} -->\n<p class=\"iss-project-chapter__kicker\">Worum es geht</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Die Wilhelminenhofstraße als Lebensnerv von Schöneweide.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Das Stadtlabor nahm die Wilhelminenhofstraße nicht nur als Verkehrsraum, sondern als verdichteten Erinnerungs- und Industriekorridor in den Blick. Zwischen Ostalgie, Alltag und Neugier wurden Geschichten, Bilder, Informationen und Wünsche gesammelt, die in eine Ausstellung einflossen.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Der Industriesalon brachte dafür sein vorhandenes Fotomaterial zur Geschichte der Straße ein. Besonders wichtig waren Fotodokumentationen aus den Jahren 1962, 1989 und 1992; ergänzt werden sollte eine neue Dokumentation aus dem Jahr 2022.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:columns {\"className\":\"iss-project-chapter__cards\"} -->\n<div class=\"wp-block-columns iss-project-chapter__cards\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"iss-context-panel\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-context-panel\"><!-- wp:paragraph {\"className\":\"iss-context-panel__label\"} -->\n<p class=\"iss-context-panel__label\">Straße</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Die Wilhelminenhofstraße wird als historischer, sozialer und gegenwärtiger Stadtraum gelesen.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"iss-context-panel\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-context-panel\"><!-- wp:paragraph {\"className\":\"iss-context-panel__label\"} -->\n<p class=\"iss-context-panel__label\">Archiv</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Fotodokumentationen aus 1962, 1989 und 1992 bilden den historischen Grundstock.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"iss-context-panel\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-context-panel\"><!-- wp:paragraph {\"className\":\"iss-context-panel__label\"} -->\n<p class=\"iss-context-panel__label\">Nachbarschaft</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Bewohnerinnen und Bewohner wurden eingeladen, eigene Erinnerungen und Beobachtungen einzubringen.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"iss-project-chapter\",\"layout\":{\"type\":\"default\"},\"anchor\":\"konzept\"} -->\n<section id=\"konzept\" class=\"wp-block-group iss-project-chapter\"><!-- wp:paragraph {\"className\":\"iss-project-chapter__kicker\"} -->\n<p class=\"iss-project-chapter__kicker\">Konzept</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Sammeln, zeigen, weiterfragen.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Das Projekt war als wachsende Ausstellung angelegt. Es sollte nicht nur fertige Ergebnisse präsentieren, sondern Material aufnehmen, Gespräche auslösen und die Straße Haus für Haus als gemeinsamen Wissensraum öffnen.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"className\":\"is-style-iss-list-rail\"} -->\n<ul class=\"wp-block-list is-style-iss-list-rail\"><!-- wp:list-item -->\n<li><strong>Vor Ort sammeln:</strong> Erinnerungen, Bilder, Informationen und Wünsche wurden direkt in der Wilhelminenhofstraße aufgenommen.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Material zurückspielen:</strong> Historische Fotos und Dokumente wurden den Bewohnerinnen und Bewohnern gezeigt, damit neue Geschichten und Hinweise entstehen konnten.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Museumsferne Nachbarschaft einbeziehen:</strong> Das Stadtlabor suchte den Dialog nicht nur im Ausstellungsraum, sondern an den Häusern und im Alltag der Straße.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Ausstellung erweitern:</strong> Neue Beiträge aus Gesprächen, Street-Prints, Porträts und Führungen ergänzten den Bestand im Prozess.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Arbeitsweise in vier Schritten.</h3>\n<!-- /wp:heading -->\n\n<!-- wp:list {\"ordered\":true,\"className\":\"is-style-iss-list-steps\"} -->\n<ol class=\"wp-block-list is-style-iss-list-steps\"><!-- wp:list-item -->\n<li>Vorhandene Fotodokumentationen und Schriftdokumente zur Straße sichten.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Mit einem Info-Mobil an einzelnen Häusern präsent sein und Gespräche anstoßen.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Erinnerungen, Bilder, Wünsche und neue Beobachtungen in die Ausstellung aufnehmen.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Die Ergebnisse in Ausstellungsstationen, Führungen und öffentlichen Gesprächsformaten sichtbar machen.</li>\n<!-- /wp:list-item --></ol>\n<!-- /wp:list --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"iss-project-chapter\",\"layout\":{\"type\":\"default\"},\"anchor\":\"mitwirken\"} -->\n<section id=\"mitwirken\" class=\"wp-block-group iss-project-chapter\"><!-- wp:paragraph {\"className\":\"iss-project-chapter__kicker\"} -->\n<p class=\"iss-project-chapter__kicker\">Mitwirken</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Anwohnerwissen, künstlerische Beiträge und historische Vermittlung.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Das Stadtlabor lebte von Beiträgen aus unterschiedlichen Rollen: Menschen aus der Straße, Künstlerinnen und Künstler, Fotografen, Vermittler und Moderatoren steuerten jeweils eine andere Form von Wissen bei.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"className\":\"is-style-iss-list-facts\"} -->\n<ul class=\"wp-block-list is-style-iss-list-facts\"><!-- wp:list-item -->\n<li><strong>Bewohnerinnen und Bewohner:</strong> Erinnerungen, Alltagserfahrungen, Bilder, Hinweise und Wünsche zur Wilhelminenhofstraße.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Sonja van Bergen und Albert Markert:</strong> Street-Prints, Drucke und Frottagen von Steinen, Kanaldeckeln und Spuren im Straßenraum.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Georg Krause:</strong> Porträts von Geschäftsleuten aus der Wilhelminenhofstraße aus dem Jahr 2012.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Thomas Irmer:</strong> historische Führung zur architektonischen und ökonomischen Entwicklung der Straße.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Dirk Reuter und Christian Ziems:</strong> Moderation der „Akademie für Alles“ als Gesprächsformat für persönliches Erfahrungswissen.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"iss-project-chapter iss-project-chapter\\u002d\\u002dwide\",\"layout\":{\"type\":\"default\"},\"anchor\":\"material\"} -->\n<section id=\"material\" class=\"wp-block-group iss-project-chapter iss-project-chapter--wide\"><!-- wp:paragraph {\"className\":\"iss-project-chapter__kicker\"} -->\n<p class=\"iss-project-chapter__kicker\">Material</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Fotos, Street-Prints, Porträts und Stadtwissen.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Die Materialien zeigen die Wilhelminenhofstraße als Archiv und Gegenwart zugleich. Historische Fotodokumentationen werden mit neuen künstlerischen und nachbarschaftlichen Beiträgen zusammengeführt.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:columns {\"verticalAlignment\":\"center\",\"className\":\"iss-project-chapter__cards\"} -->\n<div class=\"wp-block-columns are-vertically-aligned-center iss-project-chapter__cards\"><!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"40%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:40%\"><!-- wp:group {\"className\":\"iss-media-card iss-media-card\\u002d\\u002dcover iss-media-card\\u002d\\u002dframed\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-media-card iss-media-card--cover iss-media-card--framed\"><!-- wp:image {\"id\":5912,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"/wp-content/uploads/2022/10/Abdeckung_1-Grafik-Albert-Markert-768x1024.jpg\" alt=\"Street-Print Grafik von Albert Markert für das Stadtlabor\" class=\"wp-image-5912\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"60%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:60%\"><!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Straße als Druckstock</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Die Street-Prints verschoben den Blick von der großen Industriegeschichte auf die Oberflächen der Straße. Abdrücke von Steinen, Kanaldeckeln und anderen Dingen machten sichtbar, was im Alltag leicht übersehen wird.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"className\":\"is-style-iss-list-facts\"} -->\n<ul class=\"wp-block-list is-style-iss-list-facts\"><!-- wp:list-item -->\n<li>Fotodokumentationen der Wilhelminenhofstraße aus 1962, 1989 und 1992</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>geplante neue Dokumentation des Straßenraums im Jahr 2022</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Street-Prints, Drucke und Frottagen von Sonja van Bergen und Albert Markert</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Porträts von Geschäftsleuten aus der Straße von Georg Krause</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Kontext zum ehemaligen WF-Kulturhaus aus Führung und Archivbestand</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"iss-project-chapter\",\"layout\":{\"type\":\"default\"},\"anchor\":\"rueckblick\"} -->\n<section id=\"rueckblick\" class=\"wp-block-group iss-project-chapter\"><!-- wp:paragraph {\"className\":\"iss-project-chapter__kicker\"} -->\n<p class=\"iss-project-chapter__kicker\">Rückblick</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Vom Auftakt zur Akademie für Alles.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list {\"ordered\":true,\"className\":\"is-style-iss-list-steps\"} -->\n<ol class=\"wp-block-list is-style-iss-list-steps\"><!-- wp:list-item -->\n<li><strong>30. April 2022:</strong> Auftaktveranstaltung im Industriesalon mit Einladung zum Gespräch über das Stadtlabor.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>September 2022:</strong> Ausstellung im Prozess mit Material im Industriesalon sowie weiteren Präsentationen bei der Stiftung Reinbeckhallen und in der Wilhelmine 5.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>11. September 2022:</strong> Sonderführung am Tag des Offenen Denkmals mit Thomas Irmer durch die Wilhelminenhofstraße und zum ehemaligen WF-Kulturhaus.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>14. und 15. Oktober 2022:</strong> Update mit Street-Prints in der Galerie Schöneweide und Porträts von Geschäftsleuten aus der Straße.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>28. Oktober 2022:</strong> Start der „Akademie für Alles“ mit persönlichem Erfahrungswissen über, auf und unter der Wilhelminenhofstraße.</li>\n<!-- /wp:list-item --></ol>\n<!-- /wp:list --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"iss-project-chapter\",\"layout\":{\"type\":\"default\"},\"anchor\":\"kontakt\"} -->\n<section id=\"kontakt\" class=\"wp-block-group iss-project-chapter\"><!-- wp:paragraph {\"className\":\"iss-project-chapter__kicker\"} -->\n<p class=\"iss-project-chapter__kicker\">Kontakt</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Hinweise, Erinnerungen und Material zum Projekt.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Wer ergänzende Hinweise, Erinnerungen oder Material zur Wilhelminenhofstraße und zum Stadtlabor hat, erreicht den Industriesalon über den allgemeinen Kontakt. </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:industriesalon/field {\"key\":\"contact.email\",\"tagName\":\"p\",\"linkMode\":\"email\",\"label\":\"E-Mail:\",\"hrefSuffix\":\"?subject=Stadtlabor%20Wilhelminenhofstra%C3%9Fe\"} /--></section>\n<!-- /wp:group --></div>\n<!-- /wp:group -->','Stadtlabor Wilhelminenhofstraße','Stadtlabor Wilhelminenhofstraße war eine wachsende Ausstellung und ein Nachbarschaftsexperiment zur wichtigsten Straße Oberschöneweides: Erinnerungen, Bilder, Archivmaterial und Wünsche wurden vor Ort gesammelt und als Ausstellung im Prozess sichtbar gemacht.','publish','closed','closed','','stadtlabor-wilhelminenhofstrasse','','','2026-06-14 21:12:27','2026-06-14 19:12:27','',0,'/projekte/stadtlabor-wilhelminenhofstrasse/',40,'projekt','',0),
(24819,1,'2026-05-13 20:27:48','2026-05-13 18:27:48','<!-- wp:group {\"className\":\"iss-project-dossier\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-project-dossier\"><!-- wp:paragraph {\"className\":\"iss-project-dossier__lead\"} -->\n<p class=\"iss-project-dossier__lead\">Industrieabfälle ist eine Workshop-Reihe zur Industriekultur mit Kindern und Eltern: Geräusche, Stimmen, Fundstücke und Geschichten aus Schöneweide werden gesammelt, bearbeitet und als digitales Radio erfahrbar.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:iss/dense-image-wall {\"editMode\":\"annotate\",\"items\":[{\"id\":11054,\"url\":\"/wp-content/uploads/2025/12/Funkeln-WebsiteII.jpg\",\"alt\":\"\",\"kicker\":\"\",\"title\":\"\",\"text\":\"\",\"caption\":\"\",\"captionHtml\":\"\",\"className\":\"\",\"captionClassName\":\"\",\"linkUrl\":\"\",\"colSpan\":2,\"rowSpan\":3},{\"id\":11058,\"url\":\"/wp-content/uploads/2025/12/Industrieabfaelle-Logo.png\",\"alt\":\"\",\"kicker\":\"\",\"title\":\"\",\"text\":\"\",\"caption\":\"\",\"captionHtml\":\"\",\"className\":\"\",\"captionClassName\":\"\",\"linkUrl\":\"\",\"colSpan\":1,\"rowSpan\":2},{\"id\":11053,\"url\":\"/wp-content/uploads/2025/12/industrieabfaelle2025_a3_final.jpg\",\"alt\":\"\",\"kicker\":\"\",\"title\":\"\",\"text\":\"\",\"caption\":\"\",\"captionHtml\":\"\",\"className\":\"\",\"captionClassName\":\"\",\"linkUrl\":\"\",\"colSpan\":1,\"rowSpan\":2},{\"id\":10635,\"url\":\"/wp-content/uploads/2025/03/Funkeln2-bi.jpg\",\"alt\":\"\",\"kicker\":\"\",\"title\":\"\",\"text\":\"\",\"caption\":\"\",\"captionHtml\":\"\",\"className\":\"\",\"captionClassName\":\"\",\"linkUrl\":\"\",\"colSpan\":2,\"rowSpan\":3},{\"id\":10636,\"url\":\"/wp-content/uploads/2025/03/Funkeln1_bi.jpg\",\"alt\":\"\",\"kicker\":\"\",\"title\":\"Funkeln1_bi\",\"text\":\"\",\"caption\":\"\",\"captionHtml\":\"\",\"className\":\"\",\"captionClassName\":\"\",\"linkUrl\":\"\",\"colSpan\":2,\"rowSpan\":2}]} -->\n<div class=\"wp-block-group iss-dense-image-wall\"><figure class=\"wp-block-image iss-dense-image-wall__cell iss-dense-image-wall__cell--wide iss-dense-image-wall__cell--tall\" style=\"grid-column:span 2;grid-row:span 3\"><img src=\"/wp-content/uploads/2025/12/Funkeln-WebsiteII.jpg\" alt=\"\"/></figure><figure class=\"wp-block-image iss-dense-image-wall__cell iss-dense-image-wall__cell--tall\" style=\"grid-row:span 2\"><img src=\"/wp-content/uploads/2025/12/Industrieabfaelle-Logo.png\" alt=\"\"/></figure><figure class=\"wp-block-image iss-dense-image-wall__cell iss-dense-image-wall__cell--tall\" style=\"grid-row:span 2\"><img src=\"/wp-content/uploads/2025/12/industrieabfaelle2025_a3_final.jpg\" alt=\"\"/></figure><figure class=\"wp-block-image iss-dense-image-wall__cell iss-dense-image-wall__cell--wide iss-dense-image-wall__cell--tall\" style=\"grid-column:span 2;grid-row:span 3\"><img src=\"/wp-content/uploads/2025/03/Funkeln2-bi.jpg\" alt=\"\"/></figure><figure class=\"wp-block-image iss-dense-image-wall__cell iss-dense-image-wall__cell--wide iss-dense-image-wall__cell--tall iss-dense-image-wall__cell--captioned\" style=\"grid-column:span 2;grid-row:span 2\"><img src=\"/wp-content/uploads/2025/03/Funkeln1_bi.jpg\" alt=\"\"/><figcaption class=\"iss-dense-image-wall__caption\"><p class=\"iss-dense-image-wall__title\">Funkeln1_bi</p></figcaption></figure></div>\n<!-- /wp:iss/dense-image-wall -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"iss-project-chapter\",\"layout\":{\"type\":\"default\"},\"anchor\":\"worum-es-geht\"} -->\n<section id=\"worum-es-geht\" class=\"wp-block-group iss-project-chapter\"><!-- wp:paragraph {\"className\":\"iss-project-chapter__kicker\"} -->\n<p class=\"iss-project-chapter__kicker\">Worum es geht</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Aus Fabrikklang wird Radio.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Gemeinsam begeben sich Kinder, Eltern und Künstlerinnen auf Klangsuche in den Hallen der ehemaligen Fabrik. Sie fangen Geräusche ein, mischen sie mit eigenen Sounds, Stimmen und Fantasie und entwickeln daraus kurze Radioformen, Hörspiele und Klangbilder.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Das Projekt übersetzt Industriekultur nicht in eine Führung, sondern in eigenes Tun. Was sonst als Rest, Geräusch oder Nebenprodukt wahrgenommen wird, wird Material: Schritte, Hall, Maschinenassoziationen, Erzählungen und Bilder aus Schöneweide.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:columns {\"className\":\"iss-project-chapter__cards\"} -->\n<div class=\"wp-block-columns iss-project-chapter__cards\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"iss-context-panel\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-context-panel\"><!-- wp:paragraph {\"className\":\"iss-context-panel__label\"} -->\n<p class=\"iss-context-panel__label\">Kinder &amp; Eltern</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Gemeinsame Workshops, in denen Generationen über Klang und Fantasie zusammenarbeiten.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"iss-context-panel\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-context-panel\"><!-- wp:paragraph {\"className\":\"iss-context-panel__label\"} -->\n<p class=\"iss-context-panel__label\">Klang &amp; Bewegung</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Geräusche, Körper, Stimmen und Sampling werden als künstlerische Werkzeuge genutzt.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"iss-context-panel\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-context-panel\"><!-- wp:paragraph {\"className\":\"iss-context-panel__label\"} -->\n<p class=\"iss-context-panel__label\">Digitales Radio</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Die Ergebnisse werden als Installation im Industriesalon hör- und sichtbar.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"iss-project-chapter\",\"layout\":{\"type\":\"default\"},\"anchor\":\"konzept\"} -->\n<section id=\"konzept\" class=\"wp-block-group iss-project-chapter\"><!-- wp:paragraph {\"className\":\"iss-project-chapter__kicker\"} -->\n<p class=\"iss-project-chapter__kicker\">Konzept</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Erzählen, hören, sampeln, bauen.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Die Reihe verbindet Industriekultur mit künstlerischer Forschung. Ausgangspunkt sind nicht nur historische Fakten, sondern sinnliche Spuren: Klang, Raum, Stimme, Erinnerung und die Frage, wie Kinder ihren eigenen Zugang zu Industriegeschichte formulieren.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"className\":\"is-style-iss-list-rail\"} -->\n<ul class=\"wp-block-list is-style-iss-list-rail\"><!-- wp:list-item -->\n<li><strong>Klangsuche:</strong> Die Teilnehmenden sammeln Geräusche und Bewegungen im Raum und entwickeln daraus eigenes akustisches Material.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Radioformate:</strong> Sounds, Stimmen und Sampling werden zu kleinen Sendungen, Hörspielen oder Klangcollagen verdichtet.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Performance:</strong> Körper, Objekte und Bewegung bleiben sichtbar und wirken in die Audioarbeit hinein.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Installation:</strong> Die Ergebnisse werden nicht nur dokumentiert, sondern in einem alten Radio als Ausstellungsobjekt weitergeführt.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Drei thematische Einstiege.</h3>\n<!-- /wp:heading -->\n\n<!-- wp:list {\"ordered\":true,\"className\":\"is-style-iss-list-steps\"} -->\n<ol class=\"wp-block-list is-style-iss-list-steps\"><!-- wp:list-item -->\n<li><strong>Propaganda!!</strong> Bewegung, Klang-Sammeln und erste Radioformate.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Das Geräusch-Mikrofon:</strong> kritische Stimmen, Hörspiel und Klangkunst.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Stimmen aus der Geschichte:</strong> historische Klänge und Radiosendungen mit Blick auf Schöneweide.</li>\n<!-- /wp:list-item --></ol>\n<!-- /wp:list --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"iss-project-chapter\",\"layout\":{\"type\":\"default\"},\"anchor\":\"mitwirken\"} -->\n<section id=\"mitwirken\" class=\"wp-block-group iss-project-chapter\"><!-- wp:paragraph {\"className\":\"iss-project-chapter__kicker\"} -->\n<p class=\"iss-project-chapter__kicker\">Mitwirken</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Künstlerische Begleitung und Orte.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Die Workshops wurden künstlerisch von Irene Accardo und Ariel William Orah begleitet. Der Industriesalon stellte den historischen Resonanzraum bereit; Novilla ergänzte den Arbeitskontext für Radioformate, Sampling und Audiobearbeitung.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"className\":\"is-style-iss-list-facts\"} -->\n<ul class=\"wp-block-list is-style-iss-list-facts\"><!-- wp:list-item -->\n<li><strong>Irene Accardo:</strong> Bewegung, Klangforschung und kritische Stimmen.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Ariel William Orah:</strong> Sampling, Audiobearbeitung, Hörspiel und Radioformate.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Teilnehmende:</strong> Kinder und Eltern, die eigene Klänge, Stimmen und Erzählungen einbringen.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Förderung:</strong> ermöglicht durch das Programm Berliner Funkeln der Jugend- und Familienstiftung des Landes Berlin.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"iss-project-chapter iss-project-chapter\\u002d\\u002dwide\",\"layout\":{\"type\":\"default\"},\"anchor\":\"material\"} -->\n<section id=\"material\" class=\"wp-block-group iss-project-chapter iss-project-chapter--wide\"><!-- wp:paragraph {\"className\":\"iss-project-chapter__kicker\"} -->\n<p class=\"iss-project-chapter__kicker\">Material</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Radio, Plakat, Projektzeichen.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Die Materialien zeigen das Projekt als Prozess und Ergebnis: Workshopbilder, das grafische Projektmotiv, das Plakat und das digitale Radio als Installation.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:columns {\"verticalAlignment\":\"center\",\"className\":\"iss-project-chapter__cards\"} -->\n<div class=\"wp-block-columns are-vertically-aligned-center iss-project-chapter__cards\"><!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"42%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:42%\"><!-- wp:group {\"className\":\"iss-media-card iss-media-card\\u002d\\u002dcover iss-media-card\\u002d\\u002dframed\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-media-card iss-media-card--cover iss-media-card--framed\"><!-- wp:image {\"id\":11133,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"/wp-content/uploads/2026/01/Bild4.jpg\" alt=\"Industriesalonfunk als digitales Radio in der Ausstellung\" class=\"wp-image-11133\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"58%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:58%\"><!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Industriesalonfunk</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Das digitale Radio erzählt Geschichten, serviert Wellensalat und zeigt Bilder aus der Workshop-Reihe. Es macht die Ergebnisse nicht nur als Rückblick sichtbar, sondern als Objekt im Raum erfahrbar.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"className\":\"is-style-iss-list-facts\"} -->\n<ul class=\"wp-block-list is-style-iss-list-facts\"><!-- wp:list-item -->\n<li>Ergebnisse der Workshop-Reihe Industrieabfälle 2025</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Radioarbeiten von Kindern, künstlerisch begleitet von Irene Accardo und Ariel William Orah</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Bilder und Geschichten aus Schöneweide als installatives Projektarchiv</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"iss-project-chapter\",\"layout\":{\"type\":\"default\"},\"anchor\":\"rueckblick\"} -->\n<section id=\"rueckblick\" class=\"wp-block-group iss-project-chapter\"><!-- wp:paragraph {\"className\":\"iss-project-chapter__kicker\"} -->\n<p class=\"iss-project-chapter__kicker\">Rückblick</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Von der Workshop-Reihe zur Installation.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list {\"ordered\":true,\"className\":\"is-style-iss-list-steps\"} -->\n<ol class=\"wp-block-list is-style-iss-list-steps\"><!-- wp:list-item -->\n<li><strong>18. April 2025:</strong> Bewegung und Klang-Sammeln mit Irene Accardo im Industriesalon.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>27. April 2025:</strong> Entwicklung von Radioformaten mit Ariel William Orah, Sampling und Audiobearbeitung in der Novilla.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>24. Mai 2025:</strong> kritische Stimmen durch Bewegung und Klang erforschen mit Irene Accardo.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>25. Mai 2025:</strong> Hörspiele und Klangkunst mit Ariel William Orah.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>31. Mai und 1. Juni 2025:</strong> historische Klänge sammeln und daraus Radiosendungen entwickeln.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>2026:</strong> Die Ergebnisse werden als digitales Radio unter dem Titel Industriesalonfunk weitergeführt.</li>\n<!-- /wp:list-item --></ol>\n<!-- /wp:list --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"iss-project-chapter\",\"layout\":{\"type\":\"default\"},\"anchor\":\"kontakt\"} -->\n<section id=\"kontakt\" class=\"wp-block-group iss-project-chapter\"><!-- wp:paragraph {\"className\":\"iss-project-chapter__kicker\"} -->\n<p class=\"iss-project-chapter__kicker\">Kontakt</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Fragen zur Dokumentation oder zu Anschlussformaten.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Für Rückfragen zur Projektarchivierung, zur Installation oder zu möglichen Anschlussworkshops läuft der Einstieg über den allgemeinen Kontakt des Industriesalon. </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:industriesalon/field {\"key\":\"contact.email\",\"tagName\":\"p\",\"linkMode\":\"email\",\"label\":\"E-Mail:\",\"hrefSuffix\":\"?subject=Industrieabf%C3%A4lle\"} /--></section>\n<!-- /wp:group --></div>\n<!-- /wp:group -->','Industrieabfälle','Kreative Radio-Workshops für Kinder und Eltern: Industrieabfälle verbindet Klangsuche, Bewegung, Stimmen und Schöneweider Industriekultur zu einer digitalen Radio-Installation.','publish','closed','closed','','industrieabfaelle','','','2026-06-14 20:59:57','2026-06-14 18:59:57','',0,'/projekte/industrieabfaelle/',30,'projekt','',0),
(25657,1,'2026-05-28 21:59:53','2026-05-28 19:59:53','<!-- wp:group {\"className\":\"iss-project-dossier\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-project-dossier\"><!-- wp:paragraph {\"className\":\"iss-project-dossier__lead\"} -->\n<p class=\"iss-project-dossier__lead\">Stadt bauen beginnt mit Gesprächen, die sonst nicht stattfinden. Die Futura Biennale 2027 verbindet Stadtentwicklung und soziale Innovation in einem kompakten, öffentlich sichtbaren Verfahren für Schöneweide.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"iss-project-chapter\",\"layout\":{\"type\":\"default\"},\"anchor\":\"worum-es-geht\"} -->\n<section id=\"worum-es-geht\" class=\"wp-block-group iss-project-chapter\"><!-- wp:paragraph {\"className\":\"iss-project-chapter__kicker\"} -->\n<p class=\"iss-project-chapter__kicker\">Worum es geht</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Stadt bauen beginnt mit Gesprächen, die sonst nicht stattfinden.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Die Futura Biennale 2027 verbindet Stadtentwicklung und soziale Innovation in einem kompakten, öffentlich sichtbaren Verfahren. Sie überträgt die Energie eines interdisziplinären Sprints auf den Maßstab eines Stadtteils und koppelt die Ergebnisse an eine Messe für techno-soziale Innovation, auf der Ideen, Räume und Kapital zueinanderfinden.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:columns {\"className\":\"iss-project-chapter__cards\"} -->\n<div class=\"wp-block-columns iss-project-chapter__cards\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"iss-context-panel\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-context-panel\"><!-- wp:paragraph {\"className\":\"iss-context-panel__label\"} -->\n<p class=\"iss-context-panel__label\">12 Tage</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Lab und Messe in vier Phasen, von der Standortbegehung bis zur Preisvergabe.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"iss-context-panel\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-context-panel\"><!-- wp:paragraph {\"className\":\"iss-context-panel__label\"} -->\n<p class=\"iss-context-panel__label\">2 Spuren</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Wohnen und Arbeiten neu gedacht sowie soziale Infrastruktur im Quartier.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"iss-context-panel\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-context-panel\"><!-- wp:paragraph {\"className\":\"iss-context-panel__label\"} -->\n<p class=\"iss-context-panel__label\">3+ Flächen</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Eigentümer mit Flächenzusage sind Bedingung für echte Umsetzungspreise.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Schöneweide, ein Frühsommermorgen 2032.</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Wir hatten den Mut, gemeinsam zu entwerfen, zu erproben und durchzuhalten. Heute zeigt sich, was 2025 mit einer Skizze auf der ersten Futura begann und was 2026 mit einem Vorbereitungstreffen weitergedacht wurde.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Du steigst am S-Bahnhof aus, der Wind kommt von der Spree. Auf dem Weg zum Wasser läufst Du durch ein <strong>Hybrid-Quartier</strong>, in dem urbanes Leben und Arbeiten neu verbunden sind. Du passierst den <strong>Klima-Sensor-Garten</strong>, in dem Luft, Lärm und Wärme des Quartiers in Lichtsäulen sichtbar werden. Daneben der <strong>Bauhof für zirkuläres Bauen</strong>, ein paar Schritte weiter das <strong>Bio-Fashion-Atelier</strong>, in dessen Schaufenstern Mycelium-Leder neben 3D-gedruckten Garderoben hängt.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Weiter am <strong>Familien-Coworking</strong> vorbei und am <strong>Handwerker-Bildungs-Hof</strong>, in dem Schmiede, 3D-Drucker und Lehrlinge nebeneinander arbeiten. Auf der Bewegungs-Wiese Schatteninseln, Schwammstadt-Boden und an der Kante zur Spree die Spreeterrassen zum Chillen.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Du weißt: nichts davon kam von allein. Hinter jedem dieser Orte stehen Zielkonflikte und radikale Kompromisse zwischen Wachstum und Erhalt, zwischen Privatem und Öffentlichem, zwischen schnell und sorgfältig. Am Ufer angekommen drehst Du Dich um und siehst Dein Ziel: den Salon der Übermorgen, vormals Industriesalon Schöneweide, heute beides, Speicher der Geschichte und Labor der Übermorgen.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Konkrete Vorhaben, keine Absichtserklärungen.</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Nach der Durchführung liegen konkrete Projekt- und Nutzungsideen für benannte Flächen, Infrastrukturen und öffentliche Räume in Schöneweide vor. Es gibt belastbare Kooperationen zwischen Eigentümern, Wissenschaft, Zivilgesellschaft, Verwaltung und Finanzierungspartnern.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Sichtbare Prototypen und eine geschärfte Erzählung tragen den Standort in die Öffentlichkeit. Und es gibt einen verabredeten Folgeprozess mit nächsten Schritten, Zuständigkeiten und Anschlussoptionen: Die Patenschaften laufen über mindestens zwölf Monate, ein jährliches Follow-up bilanziert den Stand, und die Futura 2029 baut auf den Ergebnissen auf.</p>\n<!-- /wp:paragraph --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"iss-project-chapter iss-project-chapter\\u002d\\u002dwide\",\"layout\":{\"type\":\"default\"},\"anchor\":\"konzept\"} -->\n<section id=\"konzept\" class=\"wp-block-group iss-project-chapter iss-project-chapter--wide\"><!-- wp:paragraph {\"className\":\"iss-project-chapter__kicker\"} -->\n<p class=\"iss-project-chapter__kicker\">Konzept</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Zwölf Tage. Zwei Spuren. Ein Stadtteil.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Vier Phasen, die nicht beliebig sind: vom gemeinsamen Problemverständnis über den Lab-Sprint und die Tragfähigkeitsprüfung bis zur Messe für techno-soziale Innovation. Schöneweide ist dabei nicht Kulisse, sondern Gegenstand und Umsetzungsort.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Ein Sprint, der weiterträgt, auf Stadtteil-Maßstab.</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Die Futura überträgt die Energie eines interdisziplinären Sprints auf den Maßstab eines Stadtteils und koppelt die Ergebnisse an eine Messe für soziale Innovation, auf der Ideen, Räume und Kapital zueinanderfinden. Sie öffnet einen Korridor, in dem spätere Entscheidungen über Flächen, Nutzungen und Partnerschaften schneller, offener und besser informiert getroffen werden können.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Was hier entworfen wird, soll hier erprobt, verbunden und weitergeführt werden. Die Futura ist Startpunkt eines strukturierten Folgeprozesses, nicht dessen Ersatz.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Vier Phasen über zwölf Tage.</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Die bisher diskutierte Variante von zehn Lab-Tagen wird verworfen. Sie ist für Hackathon-Energie zu lang und für Stadtentwicklung zu kurz. Die neue Dramaturgie nimmt beide Spannungen ernst.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:columns {\"className\":\"iss-project-chapter__cards\"} -->\n<div class=\"wp-block-columns iss-project-chapter__cards\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"iss-context-panel\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-context-panel\"><!-- wp:paragraph {\"className\":\"iss-context-panel__label\"} -->\n<p class=\"iss-context-panel__label\">Phase 1</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\">Framing</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Vorab werden die Aufgabenstellungen mit den Kernakteuren geschärft. Die Teams kommen in Schöneweide an, lernen den Standort durch kuratierte Begehungen kennen und treffen auf Eigentümer, Verwaltung und Zivilgesellschaft. Am Ende steht nicht der erste Entwurf, sondern das gemeinsame Problemverständnis.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"iss-context-panel\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-context-panel\"><!-- wp:paragraph {\"className\":\"iss-context-panel__label\"} -->\n<p class=\"iss-context-panel__label\">Phase 2</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\">Lab-Sprint</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Der eigentliche Hackathon-Kern. Die Teams arbeiten in zwei thematisch unterschiedenen Spuren, die nebeneinander laufen und am Schlusstag in einer gemeinsamen Synthese konvergieren. Der Sprint ist geschlossen, intensiv, mit klaren Deliverables.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:columns {\"className\":\"iss-project-chapter__cards\"} -->\n<div class=\"wp-block-columns iss-project-chapter__cards\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"iss-context-panel\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-context-panel\"><!-- wp:paragraph {\"className\":\"iss-context-panel__label\"} -->\n<p class=\"iss-context-panel__label\">Phase 3</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\">Schärfung</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Die Entwürfe treffen auf Eigentümer, Fachleute, Verwaltung und Finanzierungspartner. Hier findet die erste Tragfähigkeitsprüfung statt. Diese Phase macht den Unterschied zwischen naivem Entwurf und anschlussfähiger Konzeption.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"iss-context-panel\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-context-panel\"><!-- wp:paragraph {\"className\":\"iss-context-panel__label\"} -->\n<p class=\"iss-context-panel__label\">Phase 4</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\">Messe für techno-soziale Innovation</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Die öffentliche Phase. Ergebnisausstellung der Lab-Teams, Flächen-Präsentationen der Eigentümer, Panels, Science Slam, Souveränitäts-Labs, Jugend-Programm. Die Messe ist kein Ausstellungsparcours, sondern ein aktiver Marktplatz mit zweistufiger Bewertung und Umsetzungspreisen.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Zwei Hauptspuren, ein Jugend-Strang, der eingreift.</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Die Futura 2027 arbeitet mit zwei parallelen Hauptspuren, ergänzt um einen Jugend-Strang, der in beide Spuren eingreift. Querschnittsthemen wie digitale Souveränität, KI-gestützte Stadtplanung, Mobilität und Kreativwirtschaft fließen ein, werden aber nicht als eigenständige Tracks geführt. Das schärft den Fokus.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\">Wohnen und Arbeiten neu gedacht</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Hybride Nachbarschaften auf bestehenden Gewerbeflächen. Wohnen wird nicht als isoliertes Problem behandelt, sondern flächenbezogen und Schöneweide-spezifisch verhandelt: Wie entstehen neue Mischnutzungen, die Gewerbeerhalt und Wohnraumbedarf verbinden?</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\">Soziale Infrastruktur im Quartier</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Bildung, Versorgung, Begegnung. Wie trägt ein wachsendes Quartier seine soziale Grundausstattung? Welche Rolle spielen Genossenschaften, Vereine, Initiativen? Welche Räume fehlen, welche sind ungenutzt?</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\">Jugend konstitutiv, nicht dekorativ</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Jedes Team hat mindestens zwei Teilnehmende unter 25 Jahren. Ein Teil der Aufgabenstellungen wird von Jugendlichen selbst formuliert und von ihnen kuratiert, nicht nur moderiert. Schulen aus Schöneweide und die HTW Berlin werden als Partner gewonnen. Ein separater Jugend-Track wird abgelehnt, weil er erfahrungsgemäß zum Nebentisch wird.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Drei Formate für drei Resonanzräume.</h3>\n<!-- /wp:heading -->\n\n<!-- wp:list {\"className\":\"is-style-iss-list-rail\"} -->\n<ul class=\"wp-block-list is-style-iss-list-rail\"><!-- wp:list-item -->\n<li><strong>Hackathon:</strong> Teams aus Praxis, Wissenschaft und Kreativwirtschaft entwickeln in wenigen Tagen Lösungen für reale Schöneweider Flächen.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Wettbewerb der Vereine, Initiativen und Einrichtungen:</strong> Akteure des Quartiers bringen Vorschläge ein, die direkt aus Schöneweide kommen und vor Ort Resonanz finden müssen.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Schüler:innen- und Studierenden-Labs:</strong> HTW Berlin, Schulen und weitere Hochschulen koppeln Lehre und Forschung an reale Aufgabenstellungen.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Zweistufig, und nur dort, wo beide Kreise tragen.</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Die Bewertung folgt zwei Kreisen, die gleichgewichtig nebeneinander stehen. Die Fachjury beurteilt Tragfähigkeit, Umsetzbarkeit, Innovationsgehalt und Passung zu Schöneweide, besetzt mit Wissenschaft, Planungspraxis, Verwaltung, Kreativwirtschaft und Zivilgesellschaft.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Das Umsetzungsvotum kommt vom Messepublikum, von Eigentümern und Finanziers. Sie vergeben ein verbindliches Votum für das Projekt, dem sie tatsächlich Raum, Kapital oder Patenschaft zusagen würden. Nicht Applaus entscheidet, sondern Absicht.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\">Umsetzungspreise, keine Geldpreise, sondern Zugänge</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Die Futura vergibt keine Geldpreise. Die Preise sind Zugänge: zu Flächen, zu Patenschaften, zu Finanzierung und zu Sichtbarkeit. Reale Umsetzungsorte in Schöneweide, mindestens zwölf Monate Begleitung, konkrete Gesprächszugänge und dokumentarische Sichtbarkeit ersetzen die reine Preisgeste.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Was die Futura braucht, um zu gelingen.</h3>\n<!-- /wp:heading -->\n\n<!-- wp:list {\"className\":\"is-style-iss-list-facts\"} -->\n<ul class=\"wp-block-list is-style-iss-list-facts\"><!-- wp:list-item -->\n<li><strong>Räumlich:</strong> Mindestens drei Eigentümer in Schöneweide müssen vor Beginn benannte Flächen zusagen, die als Umsetzungsräume dienen können.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Finanziell:</strong> Ein tragfähiges Modell aus Fördermitteln, Sponsoring, Stiftungsmitteln und moderaten Teilnahmebeiträgen, realistisch im unteren bis mittleren sechsstelligen Bereich.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Institutionell:</strong> Eine Verankerung, die die Futura über ein einmaliges Event hinaus trägt, etwa durch Industriesalon, HTW Berlin, Bezirk oder Land Berlin.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Kuratorisch:</strong> Ein benanntes Kuratorenteam mit Erfahrung in interdisziplinären Sprints, Stadtentwicklung und Messeformaten.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Kommunikativ:</strong> Eine Strategie, die die Futura nicht erst zur Messe, sondern bereits in der Ansprache-Phase sichtbar macht.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"iss-project-chapter\",\"layout\":{\"type\":\"default\"},\"anchor\":\"mitwirken\"} -->\n<section id=\"mitwirken\" class=\"wp-block-group iss-project-chapter\"><!-- wp:paragraph {\"className\":\"iss-project-chapter__kicker\"} -->\n<p class=\"iss-project-chapter__kicker\">Mitwirken</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Was bringst Du mit: Idee, Räume, Zeit, Geld, Wissen, Patenschaft?</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Die Futura Biennale 2027 lebt vom Verbund. Drei bis fünf Schlüsselakteure entscheiden, ob sie stattfindet. Wer jetzt einsteigt, prägt das Format mit: Spuren, Aufgabenstellungen, Bewertungskreis, Folgeprozess. Es gibt keinen fertigen Plan, den man bestätigt. Es gibt einen Korridor, den wir zusammen öffnen.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Erstes Vorbereitungstreffen</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>19. Mai 2026, 18 Uhr, Industriesalon Schöneweide, Reinbeckstraße 10, 12459 Berlin. Vor der Sommerpause möchten wir mit einer innovativen Konzeption gemeinsam durchstarten: drei Fragen, ein Abend, viele Stimmen.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"className\":\"is-style-iss-list-facts\"} -->\n<ul class=\"wp-block-list is-style-iss-list-facts\"><!-- wp:list-item -->\n<li>Welches Vorhaben für Schöneweide 2030 würdest Du gerne in der Futura aufgegriffen sehen?</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Was bringst Du selbst mit: Idee, Räume, Zeit, Geld, Wissen, Patenschaft?</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Wer fehlt noch am Tisch, wen sollten wir unbedingt einladen?</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Vier Rollen, ohne die die Futura nicht stattfindet.</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Erst wenn diese Gespräche geführt sind, lohnt die weitere Verfeinerung des Konzepts. Wir suchen verbindliche Partner, keine Sympathisanten.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"className\":\"is-style-iss-list-rail\"} -->\n<ul class=\"wp-block-list is-style-iss-list-rail\"><!-- wp:list-item -->\n<li><strong>Eigentümer mit Entwicklungsinteresse:</strong> reale Flächen, Einbindung in Aufgabenstellungen, Sichtbarkeit auf Messe und im Folgeprozess, Mitsprache im Umsetzungsvotum.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Hochschulen und Forschungspartner:</strong> Studierenden-Labs, Forschungsbegleitung, Anschluss an Lehrformate, Sichtbarkeit als Standortpartner.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Finanzierungs- und Förderpartner:</strong> Anker-Förderung, Beteiligung am Umsetzungsvotum, Folgeprozess-Begleitung, Sichtbarkeit in Kommunikation und Messe.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Politische Pat:innen im Bezirk:</strong> Anbindung an Bezirk und Land, Förderkulissen, standortpolitische Einordnung, Mitsprache am Folgeprozess.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Andere Wege, die Futura zu tragen.</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Nicht jede Form der Beteiligung muss eine der vier Schlüsselrollen besetzen. Vereine, Initiativen und Einrichtungen aus dem Quartier bringen eigene Vorschläge in den Wettbewerb der Vereine, Initiativen und Einrichtungen ein. Schulen aus Schöneweide kuratieren, nicht nur moderieren, den Jugend-Strang. Praktiker:innen, Wissenschaftler:innen und Kreative bewerben sich als Teams für den Lab-Sprint.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Auch Berliner Zukunftsorte und bundesweite Transformationsareale sind eingeladen, ihre Ansätze auf der Messe zu zeigen. Die Futura bindet das Schöneweider Format bewusst in den größeren Stadtkontext ein.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"className\":\"is-style-fill\"} -->\n<div class=\"wp-block-button is-style-fill\"><a class=\"wp-block-button__link wp-element-button\" href=\"mailto:k.burmeister@industriesalon.de?subject=Futura%20Biennale%202027\">Kontakt aufnehmen</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"iss-project-chapter\",\"layout\":{\"type\":\"default\"},\"anchor\":\"material\"} -->\n<section id=\"material\" class=\"wp-block-group iss-project-chapter\"><!-- wp:paragraph {\"className\":\"iss-project-chapter__kicker\"} -->\n<p class=\"iss-project-chapter__kicker\">Zukunftsquiz</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Welcher Zukunftstyp bist Du?</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>15 Fragen, 7 Typen, 3 Minuten. Das Zukunftsquiz der Futura ist mehr als ein Spiel: Es ist ein Spiegel der eigenen Haltung zu Umbruch, Risiko und neuen Möglichkeiten. Mit Profildiagramm im Radar-Chart, drei Deutungsachsen und Zukunfts-Dating für Typ-Kompatibilität. Mobile-optimiert, ohne Login, datensparsam.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:media-text {\"mediaId\":25659,\"mediaLink\":\"/wp-content/uploads/2026/05/zukunftsquiz_qrcode-300x300.png\",\"mediaType\":\"image\",\"mediaWidth\":28,\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile is-vertically-aligned-center\" style=\"grid-template-columns:28% auto\"><figure class=\"wp-block-media-text__media\"><img src=\"/wp-content/uploads/2026/05/zukunftsquiz_qrcode-300x300.png\" alt=\"QR-Code zum Zukunftsquiz\" class=\"wp-image-25659 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:paragraph -->\n<p>Drei Minuten genügen. Das Quiz läuft auf jedem Smartphone, ohne Anmeldung. Nach den 15 Fragen bekommst Du Deinen Hauptzukunftstyp, ein Radar-Profil über alle sieben Typen und ein Zukunfts-Dating mit dem Typ, der am besten zu Dir passt.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><a href=\"https://futura-biennale.github.io/zukunftsquiz/\">Quiz öffnen</a></p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Sieben Haltungen zur Zukunft.</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Jeder Typ ist eine eigene Art, mit Umbruch umzugehen. Die meisten Menschen tragen mehrere in sich. Keine Wertung, kein Schubladen-Denken: Sieben Stimmen, von denen wir alle brauchen.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"className\":\"is-style-iss-list-facts\"} -->\n<ul class=\"wp-block-list is-style-iss-list-facts\"><!-- wp:list-item -->\n<li><strong>Captain Futures:</strong> hoffnungsvoll nach vorn, aktiv gestaltend, optimistisch und mutig.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Fluxus-Surferin:</strong> neugierig, kreativ, offen für Überraschungen und experimentierfreudig.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Techno-Pionierin:</strong> technikaffin, innovativ, datengetrieben und vernetzt.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Öko-Visionärin:</strong> nachhaltig, ganzheitlich, naturverbunden und regenerativ.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Gegenwarts-Routinier:</strong> stabil, pragmatisch und stark im Hier und Jetzt verankert.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Retro-Rebellin:</strong> traditionsbewusst, analog, kritisch gegenüber Neuem und nie ohne Haltung.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Souveräne Müßiggängerin:</strong> hört hin, geht den eigenen Takt und unterscheidet das Wichtige vom Lauten.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>Das Quiz arbeitet mit 15 Fragen, die jeweils vier Antwortoptionen anbieten. Jede Antwort fließt gewichtet in mehrere Typen ein. Nach der letzten Frage wird Dein Profil auf drei Achsen ausgewertet: Zeitorientierung, Handlungsmodus und Weltzugang. Reibung und Resonanz werden kompakt verpackt.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Die Futura arbeitet mit einer These: Stadt bauen beginnt mit Gesprächen, die sonst nicht stattfinden. Damit Gespräche entstehen, braucht es einen Anlass. Das Zukunftsquiz ist genau das: ein leichter Einstieg in eine schwere Frage. Auf der Futura 2025 lief es auf Postern, QR-Codes und Smartphones; für die Futura 2027 ist es als Onboarding, Messe-Aktivierung und spielerischer Begleiter gesetzt.</p>\n<!-- /wp:paragraph --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"iss-project-chapter\",\"layout\":{\"type\":\"default\"},\"anchor\":\"rueckblick\"} -->\n<section id=\"rueckblick\" class=\"wp-block-group iss-project-chapter\"><!-- wp:paragraph {\"className\":\"iss-project-chapter__kicker\"} -->\n<p class=\"iss-project-chapter__kicker\">Rückblick 2025</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">2025 hat etwas in Bewegung gebracht.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Die erste Futura war Versuch, Werkstatt und Auftakt zugleich: ein Format auf der Suche nach seiner Form. Was wir aus ihr lernen, prägt die Futura 2027: schärfer gefasst, mit klarerer Dramaturgie und einem Folgeprozess, der nicht beim Applaus endet.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Acht Wochen, ein Stadtteil, viele Stimmen.</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Von der Auftaktveranstaltung bis zum Finale spannten sich verschiedene Formate nebeneinander auf: Diskurs, Werkstatt, Spiel und Begegnung. Eine Auswahl der Stationen, auf die die Futura 2027 aufbaut.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"className\":\"is-style-iss-list-steps\"} -->\n<ul class=\"wp-block-list is-style-iss-list-steps\"><!-- wp:list-item -->\n<li><strong>Auftakt im Westrich:</strong> Eröffnung der ersten Futura mit Andrea Funcke und einem ersten Versuch, Lokales und Zukünftiges in einem Raum zusammenzubringen.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Bohrkerne und Philo-Café:</strong> tiefe Bohrungen in die Standortgeschichte einerseits, philosophisches Gespräch über Zukünfte andererseits.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Smart. Factory.:</strong> Industrielle Transformation, neu erzählt. Was wird aus den Hallen, wenn Produktion sich wandelt?</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Zukunftslabor und Debatten-Tangram:</strong> Werkstatt-Tag, der verschiedene Akteursperspektiven gegeneinander legt.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Krisen und Feste feiern:</strong> Krisendiagnose am Vormittag, gemeinsames Fest am Abend.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Future Booth und Finale:</strong> Zukunftspreise, Future Booth und eine Zwischenbilanz, die zeigt: hier ist mehr im Werden.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Die Schöneweider Zukunftspreise.</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Aus der ersten Futura ist mehr hervorgegangen als ein Veranstaltungs-Rückblick. Die Schöneweider Zukunftspreise haben einen ersten Träger gefunden: die Schöneweider KiezKarte, Idee Dirk Sarnoch / WERK 116, ausgezeichnet mit dem Jurypreis. Die Karte verbindet lokale Kaufkraft mit einem Bürgerfonds für Kultur, Open-Air-Kino und Nachbarschaft.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Genau dieses Muster, von der Skizze zur tragfähigen Umsetzung mit konkreten Akteuren vor Ort, soll die Futura 2027 systematisch verstetigen. Die Träger der Schöneweider Zukunftspreise werden bis zur Futura 2029 begleitet.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Drei Erkenntnisse, die das 2027er-Format prägen.</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Erstens: Energie braucht eine Dramaturgie. Die zehn Lab-Tage waren für Hackathon-Energie zu lang und für Stadtentwicklung zu kurz. Die Futura 2027 antwortet mit vier Phasen über zwölf Tage: Framing, Sprint, Schärfung, Messe.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Zweitens: Bewertung muss verbindlich werden. Applaus reicht nicht. Die zweistufige Bewertung aus Fachjury und Umsetzungsvotum sorgt dafür, dass Preise nur dort vergeben werden, wo Eigentümer, Finanziers oder Pat:innen sich konkret zusagen.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Drittens: Jugend ist konstitutiv, nicht dekorativ. Ein separater Jugend-Track wird zum Nebentisch. In der Futura 2027 hat jedes Team mindestens zwei Teilnehmende unter 25 Jahren, und ein Teil der Aufgabenstellungen wird von Jugendlichen selbst formuliert.</p>\n<!-- /wp:paragraph --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"iss-project-chapter\",\"layout\":{\"type\":\"default\"},\"anchor\":\"kontakt\"} -->\n<section id=\"kontakt\" class=\"wp-block-group iss-project-chapter\"><!-- wp:paragraph {\"className\":\"iss-project-chapter__kicker\"} -->\n<p class=\"iss-project-chapter__kicker\">Kontakt</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Reden und verbindlich werden.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Die Futura entsteht im Gespräch. Schreiben Sie kurz, was Sie interessiert, was Sie einbringen können und mit wem wir sprechen sollten. Wir melden uns innerhalb weniger Tage mit Konzeptpapier und Terminvorschlag.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Wer hinter der Futura steht.</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Eine Initiative des Industriesalon Schöneweide e.V., getragen von Vorstand, Mitgliederschaft und einem wachsenden Verbund aus Standortakteuren, Hochschulen und Zivilgesellschaft.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Klaus Burmeister</strong><br>Industriesalon Schöneweide e.V. · Vorsitz<br><a href=\"mailto:k.burmeister@industriesalon.de\">k.burmeister@industriesalon.de</a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Industriesalon Schöneweide e.V.</strong><br>Reinbeckstraße 10, 12459 Berlin<br><a href=\"mailto:info@industriesalon.de\">info@industriesalon.de</a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Anreise</h3>\n<!-- /wp:heading -->\n\n<!-- wp:industriesalon/visit-info {\"accent\":\"blue\",\"show_accessibility\":false,\"show_contact_person\":true,\"show_contact_website\":false} /-->\n\n<!-- wp:paragraph -->\n<p>Der Industriesalon liegt im historischen Kabelwerk-Areal, mitten in der Wilhelminenhof. Die Adresse ist auch der Tagungsort der Futura: Halle, Hof und Außenraum bieten Platz für Lab und Messe.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Konzeptpapier, Logo, Pressetext.</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Auf Anfrage stellen wir das aktuelle Konzeptpapier, Logo-Varianten, Pressetext und Bildmaterial aus der Futura 2025 zur Verfügung. Bitte kurzes Anschreiben mit Medium und Verwendungszweck an <a href=\"mailto:k.burmeister@industriesalon.de\">k.burmeister@industriesalon.de</a>.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"className\":\"is-style-fill\"} -->\n<div class=\"wp-block-button is-style-fill\"><a class=\"wp-block-button__link wp-element-button\" href=\"mailto:k.burmeister@industriesalon.de?subject=Futura%20Biennale%202027\">Mail schreiben</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></section>\n<!-- /wp:group --></div>\n<!-- /wp:group -->','Futura Biennale 2027','Die Futura Biennale 2027 verbindet Stadtentwicklung und soziale Innovation in Schöneweide. Zwölf Tage Lab und Messe bringen Ideen, Räume und Partner an einen Tisch.','publish','closed','closed','','futura-biennale-2027','','','2026-06-14 12:39:09','2026-06-14 10:39:09','',0,'/projekte/futura-biennale-2027/',15,'projekt','',0),
(25720,1,'2026-05-29 14:27:57','2026-05-29 12:27:57','<!-- wp:group {\"className\":\"iss-project-dossier\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-project-dossier\"><!-- wp:paragraph {\"className\":\"iss-project-dossier__lead\"} -->\n<p class=\"iss-project-dossier__lead\">Der Walk of Fame Schöneweide macht Industriekultur entlang der Wilhelminenhofstraße sichtbar. Bewegliche Sehrohre lenken den Blick auf Gebäude, Blickachsen und Geschichten, die im Alltag oft übersehen werden.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:iss/dense-image-wall {\"editMode\":\"annotate\",\"items\":[{\"id\":26425,\"url\":\"/wp-content/uploads/2026/05/image5.webp\",\"alt\":\"\",\"kicker\":\"Beispiel\",\"title\":\"\",\"text\":\"Blick auf die historische Montagehalle im \\nTransformatorenwerk Oberschöneweide\",\"caption\":\"\",\"captionHtml\":\"\",\"className\":\"\",\"captionClassName\":\"\",\"linkUrl\":\"\",\"colSpan\":2,\"rowSpan\":5},{\"id\":26426,\"url\":\"/wp-content/uploads/2026/05/image4.webp\",\"alt\":\"\",\"kicker\":\"\",\"title\":\"\",\"text\":\" 1927 wurde er in dieser Halle gebaut:        Der größte Einphasen-Transformator            der Welt \",\"caption\":\"\",\"captionHtml\":\"\",\"className\":\"\",\"captionClassName\":\"\",\"linkUrl\":\"\",\"colSpan\":1,\"rowSpan\":3},{\"id\":25803,\"url\":\"/wp-content/uploads/2026/05/walk-of-fame-spyglass.png\",\"alt\":\"Rotes Sehrohr mit historischem Blickmotiv für Walk of Fame Schöneweide\",\"kicker\":\"\",\"title\":\"Walk of Fame Schöneweide Sehrohr\",\"text\":\"\",\"caption\":\"\",\"captionHtml\":\"\",\"className\":\"\",\"captionClassName\":\"\",\"linkUrl\":\"\",\"colSpan\":1,\"rowSpan\":5},{\"id\":26424,\"url\":\"/wp-content/uploads/2026/05/image6.webp\",\"alt\":\"\",\"kicker\":\"Der Künstler\",\"title\":\"Rainer Düvell \",\"text\":\"Als Künstler und Architekt hat er zahlreiche\\nAusstellungen und Installationen realisiert\",\"caption\":\"\",\"captionHtml\":\"\",\"className\":\"\",\"captionClassName\":\"\",\"linkUrl\":\"https://www.transform-info.de/rainer-duvell/\",\"colSpan\":1,\"rowSpan\":2},{\"id\":26427,\"url\":\"/wp-content/uploads/2026/05/image3.webp\",\"alt\":\"\",\"kicker\":\"\",\"title\":\"Walk of Fame Schöneweide\",\"text\":\"ist gedeckt von der Projektförderung des Vereins durch die Senatsverwaltung für Wirtschaft, \\nIndustrie und Betriebe und einen Zuschuss aus bezirksübergreifenden CItyTax-Mitteln.\",\"caption\":\"\",\"captionHtml\":\"\",\"className\":\"\",\"captionClassName\":\"\",\"linkUrl\":\"https://industriekultur.berlin/erleben/festival/\",\"colSpan\":4,\"rowSpan\":1}]} -->\n<div class=\"wp-block-group iss-dense-image-wall\"><figure class=\"wp-block-image iss-dense-image-wall__cell iss-dense-image-wall__cell--wide iss-dense-image-wall__cell--tall iss-dense-image-wall__cell--captioned\" style=\"grid-column:span 2;grid-row:span 5\"><img src=\"/wp-content/uploads/2026/05/image5.webp\" alt=\"\"/><figcaption class=\"iss-dense-image-wall__caption\"><p class=\"iss-dense-image-wall__kicker\">Beispiel</p><p class=\"iss-dense-image-wall__text\">Blick auf die historische Montagehalle im \nTransformatorenwerk Oberschöneweide</p></figcaption></figure><figure class=\"wp-block-image iss-dense-image-wall__cell iss-dense-image-wall__cell--tall iss-dense-image-wall__cell--captioned\" style=\"grid-row:span 3\"><img src=\"/wp-content/uploads/2026/05/image4.webp\" alt=\"\"/><figcaption class=\"iss-dense-image-wall__caption\"><p class=\"iss-dense-image-wall__text\"> 1927 wurde er in dieser Halle gebaut:        Der größte Einphasen-Transformator            der Welt </p></figcaption></figure><figure class=\"wp-block-image iss-dense-image-wall__cell iss-dense-image-wall__cell--tall iss-dense-image-wall__cell--captioned\" style=\"grid-row:span 5\"><img src=\"/wp-content/uploads/2026/05/walk-of-fame-spyglass.png\" alt=\"Rotes Sehrohr mit historischem Blickmotiv für Walk of Fame Schöneweide\"/><figcaption class=\"iss-dense-image-wall__caption\"><p class=\"iss-dense-image-wall__title\">Walk of Fame Schöneweide Sehrohr</p></figcaption></figure><figure class=\"wp-block-image iss-dense-image-wall__cell iss-dense-image-wall__cell--tall iss-dense-image-wall__cell--captioned\" style=\"grid-row:span 2\"><a href=\"https://www.transform-info.de/rainer-duvell/\"><img src=\"/wp-content/uploads/2026/05/image6.webp\" alt=\"\"/></a><figcaption class=\"iss-dense-image-wall__caption\"><p class=\"iss-dense-image-wall__kicker\">Der Künstler</p><p class=\"iss-dense-image-wall__title\">Rainer Düvell </p><p class=\"iss-dense-image-wall__text\">Als Künstler und Architekt hat er zahlreiche\nAusstellungen und Installationen realisiert</p></figcaption></figure><figure class=\"wp-block-image iss-dense-image-wall__cell iss-dense-image-wall__cell--wide iss-dense-image-wall__cell--captioned\" style=\"grid-column:span 4\"><a href=\"https://industriekultur.berlin/erleben/festival/\"><img src=\"/wp-content/uploads/2026/05/image3.webp\" alt=\"\"/></a><figcaption class=\"iss-dense-image-wall__caption\"><p class=\"iss-dense-image-wall__title\">Walk of Fame Schöneweide</p><p class=\"iss-dense-image-wall__text\">ist gedeckt von der Projektförderung des Vereins durch die Senatsverwaltung für Wirtschaft, \nIndustrie und Betriebe und einen Zuschuss aus bezirksübergreifenden CItyTax-Mitteln.</p></figcaption></figure></div>\n<!-- /wp:iss/dense-image-wall -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"iss-project-chapter\",\"layout\":{\"type\":\"default\"},\"anchor\":\"worum-es-geht\"} -->\n<section id=\"worum-es-geht\" class=\"wp-block-group iss-project-chapter\"><!-- wp:paragraph {\"className\":\"iss-project-chapter__kicker\"} -->\n<p class=\"iss-project-chapter__kicker\">Worum es geht</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Industriekultur wird zum Blickpunkt im Straßenraum.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Der Walk of Fame Schöneweide ist als Auftakt und Teil des Festivals der Berliner Industriekultur geplant. Während des Festivalzeitraums vom 12. September bis 4. Oktober 2026 sollen Sehrohre entlang der Wilhelminenhofstraße den Blick auf prägende Orte der Industriekultur lenken.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Initiator und Organisator ist der Industriesalon Schöneweide e.V. Das Projekt stärkt den Standort, indem es vorhandene Gebäude, Unternehmen und Einrichtungen nicht nur beschreibt, sondern als sichtbare Stationen im öffentlichen Raum erfahrbar macht.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:columns {\"className\":\"iss-project-chapter__cards\"} -->\n<div class=\"wp-block-columns iss-project-chapter__cards\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"iss-context-panel\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-context-panel\"><!-- wp:paragraph {\"className\":\"iss-context-panel__label\"} -->\n<p class=\"iss-context-panel__label\">12.09.-04.10.2026</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Geplanter Festivalzeitraum im Rahmen der Berliner Industriekultur.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"iss-context-panel\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-context-panel\"><!-- wp:paragraph {\"className\":\"iss-context-panel__label\"} -->\n<p class=\"iss-context-panel__label\">29 Standorte</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Das Tiefbauamt Treptow-Köpenick hat Standorte für Sehrohre entlang der Wilhelminenhofstraße genehmigt.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"iss-context-panel\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-context-panel\"><!-- wp:paragraph {\"className\":\"iss-context-panel__label\"} -->\n<p class=\"iss-context-panel__label\">Eröffnung</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Geplant für den 12. September 2026 um 14 Uhr.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"iss-project-chapter\",\"layout\":{\"type\":\"default\"},\"anchor\":\"konzept\"} -->\n<section id=\"konzept\" class=\"wp-block-group iss-project-chapter\"><!-- wp:paragraph {\"className\":\"iss-project-chapter__kicker\"} -->\n<p class=\"iss-project-chapter__kicker\">Konzept</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Sehrohre als einfache, robuste Vermittlungsform.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Die Sehrohre werden von Rainer Düvell gebaut. Als Künstler und Architekt arbeitet er mit Installationen, die Raumsituationen über aktive Wahrnehmung erfahrbar machen. Für Schöneweide wird dieses Prinzip in den Stadtraum übertragen: Wer in ein Sehrohr schaut, folgt einer gesetzten Blickachse.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"className\":\"is-style-iss-list-rail\"} -->\n<ul class=\"wp-block-list is-style-iss-list-rail\"><!-- wp:list-item -->\n<li><strong>Material:</strong> oxidiertes Metall, robust genug für den öffentlichen Raum.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Beweglichkeit:</strong> Die Sehrohre können auf unterschiedliche Körpergrößen reagieren.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Vermittlung:</strong> Die Installation ersetzt keine Geschichte, sondern öffnet den ersten Blick darauf.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"iss-project-chapter\",\"layout\":{\"type\":\"default\"},\"anchor\":\"mitwirken\"} -->\n<section id=\"mitwirken\" class=\"wp-block-group iss-project-chapter\"><!-- wp:paragraph {\"className\":\"iss-project-chapter__kicker\"} -->\n<p class=\"iss-project-chapter__kicker\">Mitwirken</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Patenschaften halten den Walk of Fame im Quartier.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Zum „Fame“ von Schöneweide gehören auch die Unternehmen, Headquarter und Einrichtungen, die heute am Standort arbeiten. Sie sollen als Nachbarn sichtbar werden und zugleich helfen, die Sehrohre vor Diebstahl und Zerstörung zu schützen.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"className\":\"is-style-iss-list-facts\"} -->\n<ul class=\"wp-block-list is-style-iss-list-facts\"><!-- wp:list-item -->\n<li>Gewerbetreibende und Anwohner entlang der Wilhelminenhofstraße können als Paten angesprochen werden.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Interessenten können ein individuelles Sehrohr gestalten und bauen lassen.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Partner werden für die Festivaldauer im Industriesalon Schöneweide sichtbar gemacht.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"iss-project-chapter\",\"layout\":{\"type\":\"default\"},\"anchor\":\"material\"} -->\n<section id=\"material\" class=\"wp-block-group iss-project-chapter\"><!-- wp:paragraph {\"className\":\"iss-project-chapter__kicker\"} -->\n<p class=\"iss-project-chapter__kicker\">Material</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Flyer, Festivalbezug und Künstlerkontext.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Der Flyer verknüpft das lokale Projekt mit dem Festival der Berliner Industriekultur und stellt die Sehrohre als künstlerische Intervention im Stadtraum vor.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"className\":\"is-style-iss-list-facts\"} -->\n<ul class=\"wp-block-list is-style-iss-list-facts\"><!-- wp:list-item -->\n<li><strong>Festival:</strong> <a href=\"https://industriekultur.berlin/erleben/festival/\">Festival der Berliner Industriekultur</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Künstler:</strong> <a href=\"https://www.transform-info.de/rainer-duvell/\">Rainer Düvell</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Quelle:</strong> vierseitiger Flyer „Walk of Fame Schöneweide“, Stand 27. Mai 2026.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"iss-project-chapter\",\"layout\":{\"type\":\"default\"},\"anchor\":\"rueckblick\"} -->\n<section id=\"rueckblick\" class=\"wp-block-group iss-project-chapter\"><!-- wp:paragraph {\"className\":\"iss-project-chapter__kicker\"} -->\n<p class=\"iss-project-chapter__kicker\">Rückblick</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Stand Mai 2026.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Die Basisfinanzierung ist laut Flyer über die Projektförderung des Vereins durch die Senatsverwaltung für Wirtschaft, Energie und Betriebe sowie über bezirksübergreifende City-Tax-Mittel gedeckt. Die Standorte entlang der Wilhelminenhofstraße sind genehmigt; die nächste Aufgabe ist die Abstimmung mit Partnern und Paten im Quartier.</p>\n<!-- /wp:paragraph --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"iss-project-chapter\",\"layout\":{\"type\":\"default\"},\"anchor\":\"kontakt\"} -->\n<section id=\"kontakt\" class=\"wp-block-group iss-project-chapter\"><!-- wp:paragraph {\"className\":\"iss-project-chapter__kicker\"} -->\n<p class=\"iss-project-chapter__kicker\">Kontakt</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Abstimmung über den Industriesalon.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Für Patenschaften, Beteiligung und weitere Abstimmung bleibt die Kontaktinformation zentral gepflegt. Personenbezogene Telefon- und E-Mail-Angaben aus dem Flyer werden nicht als freie Projektprosa dupliziert.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:industriesalon/field {\"key\":\"contact.email\",\"tagName\":\"p\",\"linkMode\":\"email\",\"label\":\"E-Mail:\",\"hrefSuffix\":\"?subject=Walk%20of%20Fame%20Sch%C3%B6neweide\"} /--></section>\n<!-- /wp:group --></div>\n<!-- /wp:group -->','Walk of Fame Schöneweide','INSTALLATION MIT SEHROHREN AUF DER WILHELMINENHOFSTRAßE\n\nBürgermeister Igel und Musik, Spiel & Spaß.\nIm Rahmen des Festivals der Berliner Industriekultur 2026.','publish','closed','closed','','walk-of-fame-schoeneweide','','','2026-06-14 12:37:36','2026-06-14 10:37:36','',0,'/projekte/walk-of-fame-schoeneweide/',10,'projekt','',0);
